/* 투자의 역사 — 큰 이야기만. y 해 · t 제목 · b 무슨 일 · w 오늘 기사와 이어지는 점. 사람이 써 둔 글(로봇·토큰 0).
   숫자는 널리 알려진 기록 기준의 어림값이에요. */
window.VFM_LEARN = Object.assign(window.VFM_LEARN || {}, { history: [
  { id: "world", flag: "🌍", name: "세계 큰 줄기", intro: "400년을 스물네 장면으로. 주식회사가 태어나고 → 거품이 터지고 → 규칙이 생기고 → 벤처와 사모펀드가 나오고 → 인터넷과 AI로 돈이 몰리기까지. 장면마다 그때의 회사 이름이 나와요.", items: [
    { y: "1602", t: "첫 주식회사, 네덜란드 동인도회사", wk: "Dutch_East_India_Company", co: ["네덜란드 동인도회사(VOC)", "암스테르담 거래소"],
      toon: [["⛵", "배 한 척에 전 재산을 걸었다가 가라앉으면 끝이야."], ["🧑‍🌾", "그럼 천 명이 조금씩 내서 배 백 척을 띄우자!"]],
      b: "향신료를 실으러 아시아로 가는 배는 열 척 중 몇 척이 돌아오지 못했어요. 한 번 실패하면 상인은 파산이었어요.\n1602년 네덜란드 정부는 여러 무역 회사를 하나로 묶어 **동인도회사(VOC)**를 만들고 21년 독점권을 줬어요. 암스테르담에서만 1,100명 넘는 시민이 돈을 냈어요. 하녀와 목수도 있었어요.\n새로운 점이 두 가지였어요. 첫째, 낸 돈까지만 책임져요(유한책임). 둘째, 회사에 돈을 돌려 달라고 할 수 없는 대신 **지분을 남에게 팔 수 있어요**. 그 지분을 사고팔려고 사람들이 모인 다리 위가 세계 첫 증권거래소가 됐어요.",
      w: "'여럿이 조금씩 넣고, 조각을 사고판다'. 오늘의 주식, 펀드, 스타트업 투자가 전부 이 발명 위에 있어요." },
    { y: "1637", t: "튤립 거품", wk: "Tulip_mania", co: ["하를럼 튤립 경매", "셈페르 아우구스투스(품종)"],
      toon: [["🌷", "어제 산 알뿌리가 오늘 두 배가 됐어!"], ["🤔", "꽃은 아직 피지도 않았는데, 누가 그 값에 사 주지?"]],
      b: "부자가 된 네덜란드에서 줄무늬 튤립이 부의 상징이 됐어요. 가장 귀한 품종 '셈페르 아우구스투스' 알뿌리 하나가 암스테르담 운하 옆 집 한 채 값이었다고 전해져요.\n사람들은 꽃이 아니라 **'봄에 알뿌리를 받을 권리'가 적힌 종이**를 술집에서 사고팔았어요. 하루에도 주인이 여러 번 바뀌었어요.\n1637년 2월, 하를럼의 한 경매에 살 사람이 나타나지 않았어요. 소문은 며칠 만에 퍼졌고 값은 무너졌어요.",
      w: "거품의 원조. '더 비싸게 살 사람이 있겠지'만으로 오른 값은 그 사람이 안 나타나는 날 끝나요. 닷컴, 코인, AI 과열 기사에 늘 불려 나와요." },
    { y: "1694", t: "영란은행과 나라의 빚", wk: "Bank_of_England", co: ["영란은행(Bank of England)"],
      toon: [["👑", "전쟁할 돈이 없네. 세금은 더 못 걷고…"], ["🏦", "저희가 모아서 빌려드리죠. 대신 이자는 의회가 보증해 주세요."]],
      b: "프랑스와 전쟁 중이던 영국 왕은 돈이 필요했어요. 상인들이 **영란은행**을 세워 120만 파운드를 모아 나라에 빌려줬어요. 그 대가로 은행은 지폐를 찍을 권리를 받았어요.\n왕 개인이 아니라 의회가 세금으로 이자를 보증하자, 사람들은 나라에 돈을 빌려주는 것을 안전하다고 여기게 됐어요. **국채**가 믿을 만한 투자가 된 거예요.",
      w: "중앙은행과 국채 시장의 시작. 지금 '미국 국채 금리'가 모든 투자의 기준이 된 뿌리예요." },
    { y: "1720", t: "남해 거품과 미시시피 거품", wk: "South_Sea_Company", co: ["남해회사", "미시시피회사", "영란은행"],
      toon: [["📜", "나라 빚을 우리 회사 주식으로 바꿔 드립니다. 주가는 계속 오를 거예요!"], ["🍎", "별의 움직임은 계산해도 사람들의 광기는 계산 못 하겠군. — 뉴턴(전해지는 말)"]],
      b: "영국 **남해회사**는 나라 빚을 떠안는 대신 남미 무역 독점권을 받았어요. 무역은 거의 없었지만 주가는 반년 만에 100파운드대에서 1,000파운드 가까이 올랐어요.\n같은 때 프랑스에서는 스코틀랜드 사람 존 로가 **미시시피회사** 주식과 지폐를 한꺼번에 찍어 내며 똑같은 열풍을 만들었어요.\n1720년 가을 둘 다 무너졌어요. 조폐국장이던 뉴턴도 큰돈을 잃었다고 전해져요. 영국은 그 뒤 100년 넘게 주식회사 설립을 까다롭게 묶었어요.",
      w: "정부가 얽힌 거품과 그 뒤의 규제. '거품 → 붕괴 → 새 규칙'이라는 순서가 이때 처음 나왔어요." },
    { y: "1840년대", t: "철도 광풍", wk: "Railway_Mania", co: ["그레이트 웨스턴 철도", "영국 의회"],
      toon: [["🚂", "철도가 세상을 바꾼다! 노선만 그리면 돈이 모여요."], ["📉", "세상은 정말 바뀌었지. 내 주식은 휴지가 됐지만."]],
      b: "증기기관차가 달리자 영국 사람들은 철도 회사 주식에 몰려들었어요. 1846년 한 해에만 의회가 270개가 넘는 철도 건설 법안을 통과시켰어요.\n계획된 노선의 상당수는 지어지지 않았고 주가는 무너졌어요. 중산층 투자자 수만 명이 돈을 잃었어요.\n하지만 **철도는 남았어요.** 이때 깔린 선로가 지금도 영국 철도망의 뼈대예요.",
      w: "'거품이 꺼져도 기술과 시설은 남는다'. 닷컴 때 깔린 광케이블, 지금 AI 데이터센터를 두고 같은 말을 해요." },
    { y: "1855", t: "유한책임이 모두의 것이 되다", wk: "Limited_Liability_Act_1855", co: ["영국 의회"],
      toon: [["😰", "회사가 망하면 내 집까지 넘어간다고? 그럼 투자 안 해."], ["⚖️", "이제는 넣은 돈까지만 잃습니다."]],
      b: "그전까지 보통 회사의 주주는 회사 빚을 끝까지 책임져야 했어요. 회사가 망하면 집까지 넘어갔어요.\n1855년 영국은 **'주주는 넣은 돈까지만 책임진다'**는 유한책임을 널리 허용했고, 1862년에는 등록만 하면 누구나 주식회사를 세울 수 있게 했어요.\n모르는 사람의 회사에 돈을 넣는 일이 비로소 할 만한 일이 됐어요.",
      w: "회사 이름 뒤의 Ltd, Inc, 주식회사가 바로 이 약속이에요. 이 규칙이 없으면 스타트업 투자도 없어요." },
    { y: "1870~1911", t: "록펠러와 독점, 그리고 반독점법", wk: "Standard_Oil", co: ["스탠더드오일", "US스틸", "JP모건", "엑슨모빌·셰브론(후신)"],
      toon: [["🛢️", "경쟁사를 다 사들이면 값은 내가 정하지."], ["🏛️", "너무 커졌어. 서른네 조각으로 나누시오."]],
      b: "록펠러의 **스탠더드오일**은 경쟁 정유사를 차례로 사들여 미국 석유 정제의 약 90%를 쥐었어요. 1901년에는 은행가 JP모건이 카네기의 철강회사를 사서 합친 **US스틸**이 세계 첫 '10억 달러 기업'이 됐어요.\n미국은 1890년 셔먼 반독점법을 만들었고, 1911년 대법원은 스탠더드오일을 34개 회사로 쪼갰어요. 엑슨, 모빌, 셰브론이 그 후손이에요.\n쪼개진 회사들의 주식 값을 합치자 오히려 전보다 커졌고 록펠러는 더 부자가 됐어요.",
      w: "인수 기사에 '기업결합 심사', '반독점'이 나오는 뿌리. 구글·메타·아마존을 쪼개자는 주장도 이 판결을 본보기로 들어요." },
    { y: "1929", t: "대폭락과 대공황", wk: "Wall_Street_Crash_of_1929", co: ["뉴욕증권거래소", "JP모건", "미국 증권거래위원회(SEC)"],
      toon: [["📈", "빚내서 주식 사면 돼. 10%만 내면 나머지는 빌려줘!"], ["🥣", "3년 뒤, 무료 급식 줄이 몇 블록이야."]],
      b: "1920년대 미국은 라디오·자동차 주식 열풍이었어요. 주식 값의 10%만 내고 나머지는 빌려서 사는 사람이 많았어요.\n1929년 10월 주가가 무너지기 시작해 다우 지수는 1932년 여름까지 **약 89%** 떨어졌어요. 은행 수천 곳이 문을 닫고 네 명 중 한 명이 일자리를 잃었어요.\n미국은 1933~34년 증권법을 만들고 **SEC**를 세웠어요. '주식을 팔려면 회사의 사실을 공개하라'는 규칙이 이때 생겼어요.",
      w: "지금의 '공시'가 여기서 왔어요. 이 앱이 읽는 SEC 서류(Form D, S-1)가 그 후손이에요." },
    { y: "1946", t: "첫 벤처캐피털", wk: "Digital_Equipment_Corporation", co: ["ARDC", "DEC(디지털 이큅먼트)"],
      toon: [["🎓", "은행은 담보 없는 기술 회사에 돈을 안 빌려줘요."], ["💡", "그럼 빌려주지 말고 지분을 삽시다. 열 중 하나만 터져도 돼요."]],
      b: "하버드 교수 조르주 도리오는 전쟁 때 개발된 기술이 회사가 되려면 새로운 돈이 필요하다고 봤어요. 1946년 **ARDC**를 세워 기술 회사의 지분을 샀어요.\n1957년 MIT 출신 두 사람이 세운 컴퓨터 회사 **DEC**에 7만 달러를 넣었어요. DEC가 상장한 뒤 그 지분은 수억 달러가 됐어요.\nARDC가 번 돈의 대부분이 이 한 건에서 나왔어요.",
      w: "'대박 하나가 나머지를 다 덮는다'는 벤처 투자의 수익 구조가 처음 숫자로 증명됐어요." },
    { y: "1957", t: "8인의 배신자, 실리콘밸리의 시작", wk: "Fairchild_Semiconductor", co: ["페어차일드 반도체", "인텔", "AMD", "세쿼이아", "클라이너 퍼킨스"],
      toon: [["😤", "이 사장 밑에서는 못 하겠어. 우리끼리 나가서 만들자."], ["🤝", "회사를 세워. 돈은 내가 구해 올게. — 아서 록"]],
      b: "노벨상 수상자 쇼클리의 연구소에서 젊은 기술자 8명이 한꺼번에 나갔어요. 투자자 아서 록이 돈줄을 찾아 줘 **페어차일드 반도체**가 생겼어요.\n여기서 다시 나온 사람들이 **인텔**(1968), AMD를 세웠고, 페어차일드 출신 돈 발렌타인은 **세쿼이아**(1972)를, 유진 클라이너는 **클라이너 퍼킨스**(1972)를 만들었어요.\n한 회사에서 수십 개 회사가 가지를 쳤어요. 이들을 '페어칠드런'이라 불러요.",
      w: "'기술자가 회사를 나와 투자받아 창업하고, 성공하면 다음 창업자에게 투자한다'. 한국의 네이버·카카오·쿠팡 출신 창업도 같은 무늬예요." },
    { y: "1971", t: "나스닥, 기술 회사의 시장", wk: "Nasdaq", co: ["나스닥", "인텔", "애플", "마이크로소프트"],
      toon: [["🖥️", "객장에서 소리 지를 필요 없어요. 화면으로 거래합시다."], ["🍏", "이익이 작아도 빨리 크는 회사는 여기로 오세요."]],
      b: "1971년 세계 첫 전자 주식시장 **나스닥**이 열렸고, 같은 해 인텔이 상장했어요.\n뉴욕증권거래소에 못 가던 젊은 기술 회사들이 나스닥으로 갔어요. 애플(1980), 마이크로소프트(1986)가 여기서 상장했어요.\n1979년에는 연기금이 벤처펀드에 돈을 맡길 수 있게 규칙이 풀렸어요. 벤처로 들어오는 돈이 몇 해 만에 몇 배로 커졌어요.",
      w: "벤처 투자의 '출구'가 생긴 것. 출구(상장)가 있어야 입구(투자)에 돈이 들어와요. 한국 코스닥(1996)도 이것을 본떴어요." },
    { y: "1980년대", t: "문 앞의 야만인들: 빚으로 회사를 사다", wk: "RJR_Nabisco", co: ["KKR", "RJR 나비스코", "드렉셀 번햄 램버트", "블랙스톤(1985 설립)"],
      toon: [["💼", "내 돈은 10%만 넣고 나머지는 빚으로 삽시다. 빚은 산 회사가 갚고요."], ["🏭", "회사는 그대로인데 빚만 산더미가 됐네."]],
      b: "**KKR** 같은 사모펀드가 큰 빚을 내서 대기업을 통째로 사는 차입 매수(LBO)를 퍼뜨렸어요. 그 빚은 드렉셀의 마이클 밀켄이 만든 '정크본드'(위험하지만 이자가 높은 채권) 시장에서 나왔어요.\n정점은 1988년. 담배·과자 회사 **RJR 나비스코**를 두고 경영진과 KKR이 경쟁한 끝에 KKR이 약 250억 달러에 샀어요. 그때까지 사상 최대 인수였어요.\n1987년 10월 19일에는 다우 지수가 하루에 22.6% 떨어지는 '검은 월요일'도 있었어요.",
      w: "오늘날 사모펀드의 기술이 이때 완성됐어요. 기사에 KKR, 블랙스톤, 칼라일이 나오면 이 시대에 태어난 회사들이에요." },
    { y: "1989", t: "일본 돈이 세계를 사다", wk: "Japanese_asset_price_bubble", co: ["미쓰비시지쇼", "소니", "컬럼비아 픽처스", "록펠러센터"],
      toon: [["🗼", "도쿄 땅을 팔면 미국 전체를 살 수 있대!"], ["🎬", "영화사도, 뉴욕 한복판 빌딩도 삽시다."]],
      b: "엔화 값이 오르고 금리가 낮아지자 일본의 주식과 땅값이 치솟았어요. 닛케이 지수는 1989년 말 38,915로 정점을 찍었어요.\n넘치는 돈으로 일본 기업은 미국을 샀어요. **소니**는 영화사 컬럼비아 픽처스를, **미쓰비시지쇼**는 뉴욕 록펠러센터를 샀어요(둘 다 1989년).\n이듬해 거품이 꺼졌어요. 미쓰비시는 록펠러센터에서 큰 손해를 보고 물러났고, 일본은 긴 불황에 들어갔어요.",
      w: "돈이 넘칠 때 비싸게 산 해외 자산은 탈이 나기 쉬워요. 뒤에 중국 기업, 중동 국부펀드의 해외 인수를 볼 때 견주는 사례예요." },
    { y: "1995~2000", t: "닷컴 거품", wk: "Dot-com_bubble", co: ["넷스케이프", "아마존", "야후", "펫츠닷컴", "AOL·타임워너", "시스코"],
      toon: [["🌐", "이익? 그런 건 나중에. 지금은 방문자 수가 중요해!"], ["🧦", "양말 인형 광고로 유명했던 우리 회사, 상장 아홉 달 만에 문 닫았어요."]],
      b: "1995년 웹브라우저 회사 **넷스케이프**가 이익도 없이 상장해 첫날 주가가 두 배가 넘게 뛰었어요. 신호탄이었어요. 아마존(1997), 이베이(1998)가 뒤를 이었고 이름에 '.com'만 붙이면 돈이 몰렸어요.\n2000년 1월 **AOL이 타임워너를** 약 1,650억 달러에 합병한다고 발표했어요. 인터넷 회사가 전통 미디어 제국을 삼킨 거예요.\n나스닥은 2000년 3월 5,048에서 정점을 찍고 2002년 10월 1,114까지 **약 78%** 떨어졌어요. 펫츠닷컴은 상장 9개월 만에 청산했고, AOL타임워너는 2002년 약 990억 달러 손실을 냈어요.",
      w: "잿더미에서 아마존과 구글이 살아남았어요. AI 투자 과열을 두고 '지금이 1999년인가 1995년인가'를 묻는 이유예요." },
    { y: "2001~02", t: "엔론: 숫자를 믿을 수 있나", wk: "Enron_scandal", co: ["엔론", "월드컴", "아서 앤더슨"],
      toon: [["📊", "빚은 장부 밖 회사에 숨겨 두면 안 보여요."], ["🔍", "미국에서 일곱째로 큰 회사가 몇 주 만에 사라졌다고?"]],
      b: "에너지 회사 **엔론**은 '가장 혁신적인 기업'으로 뽑히던 회사였어요. 실제로는 빚과 손실을 장부 밖 특수 회사에 숨기고 있었어요. 2001년 12월 파산했어요.\n이듬해 통신사 **월드컴**의 더 큰 회계 부정이 드러났어요. 엔론의 장부를 봐 주던 세계 5대 회계법인 **아서 앤더슨**도 문을 닫았어요.\n미국은 2002년 사베인스-옥슬리법을 만들어 경영자가 재무제표에 직접 서명하고 책임지게 했어요.",
      w: "투자의 바탕은 '숫자를 믿을 수 있다'는 거예요. 실사와 회계 감사가 왜 그렇게 중요한지 보여 준 사건." },
    { y: "2004~07", t: "구글 상장과 사모펀드의 황금기", wk: "Googleplex", co: ["구글", "블랙스톤", "KKR", "TPG", "TXU"],
      toon: [["🔎", "창업자 주식은 한 주에 열 표입니다. 싫으면 사지 마세요."], ["🏗️", "금리가 싸니 이번엔 450억 달러짜리를 삽시다."]],
      b: "2004년 **구글**이 상장했어요. 창업자들이 의결권이 열 배인 주식을 따로 가져 지분이 줄어도 경영권을 지켰어요. 이후 기술 회사의 표준이 됐어요.\n금리가 낮던 2005~07년은 사모펀드의 황금기였어요. 2007년 KKR과 TPG가 텍사스 전력회사 **TXU**를 약 450억 달러에 샀어요. 지금도 사상 최대 차입 매수로 꼽혀요.\n같은 해 사모펀드 **블랙스톤**이 스스로 상장했어요. 꼭대기의 신호였다는 말을 들어요.",
      w: "TXU는 몇 해 뒤 파산했어요. 빚으로 산 회사는 경기가 꺾이면 가장 먼저 무너져요." },
    { y: "2008", t: "세계 금융위기", wk: "Bankruptcy_of_Lehman_Brothers", co: ["리먼브러더스", "베어스턴스", "JP모건", "AIG", "메릴린치", "뱅크오브아메리카"],
      toon: [["🏠", "집값은 안 떨어져요. 소득 안 봐도 대출해 드려요."], ["📦", "158년 된 은행이 월요일 아침에 사라졌어. 상자 들고 나왔지."]],
      b: "미국 은행들은 갚기 어려운 사람에게도 주택 대출을 해 주고, 그 대출을 묶어 '안전한 채권'으로 포장해 전 세계에 팔았어요. 집값이 떨어지자 포장이 터졌어요.\n2008년 3월 **베어스턴스**가 JP모건에 헐값에 팔렸고, 9월 15일 **리먼브러더스**가 파산했어요. 미국 역사상 가장 큰 파산이에요. 같은 주에 메릴린치는 뱅크오브아메리카에 팔리고, 보험사 **AIG**는 정부 돈 850억 달러로 살아났어요.\n미국 의회는 7,000억 달러 구제 자금을 통과시켰고, 각국 중앙은행은 금리를 0 가까이 내렸어요.",
      w: "이후 10여 년 '돈이 거의 공짜인 시대'가 스타트업 붐의 연료가 됐어요." },
    { y: "2010년대", t: "스마트폰, 유니콘, 그리고 1,000억 달러 펀드", wk: "Unicorn_(finance)", co: ["우버", "에어비앤비", "페이스북", "왓츠앱", "알리바바", "소프트뱅크 비전펀드", "텐센트"],
      toon: [["🦄", "기업가치 10억 달러 넘는 비상장 회사? 유니콘만큼 드물지."], ["💰", "한 번에 10억 달러씩 넣겠습니다. 경쟁자가 따라올 수 없게요. — 비전펀드"]],
      b: "스마트폰이 퍼지자 우버, 에어비앤비 같은 회사가 나왔어요. 2013년 투자자 에일린 리가 기업가치 10억 달러가 넘는 비상장 회사를 **'유니콘'**이라 불렀을 때는 39곳뿐이었어요. 몇 해 뒤 수백 곳이 됐어요.\n**페이스북**은 인스타그램(2012, 10억 달러)과 왓츠앱(2014, 약 190억 달러)을 샀어요. 2014년 **알리바바**는 뉴욕에서 약 250억 달러를 모아 그때까지 세계 최대 상장을 했어요.\n2017년 손정의의 **소프트뱅크 비전펀드**가 사우디 국부펀드 등의 돈 약 1,000억 달러로 문을 열었어요. 벤처펀드 하나가 그 전 미국 벤처 업계가 한 해에 모으던 돈보다 컸어요.",
      w: "회사들이 상장을 미루고 비상장으로 오래, 크게 크는 지금의 모습이 이때 굳어졌어요. 쿠팡의 가장 큰 투자자도 비전펀드였어요." },
    { y: "2019", t: "위워크와 아람코: 같은 해의 두 상장", wk: "WeWork", co: ["위워크", "소프트뱅크", "사우디 아람코"],
      toon: [["🏢", "우리는 사무실 임대업이 아니라 '의식을 높이는' 기술 회사입니다."], ["📄", "상장 서류를 읽어 보니… 1년에 19억 달러 적자네요?"]],
      b: "공유 사무실 **위워크**는 소프트뱅크에게서 기업가치 470억 달러로 투자받았어요. 2019년 상장 서류(S-1)가 공개되자 큰 적자와 창업자에게 유리한 거래들이 드러났어요. 상장은 취소됐고 기업가치는 몇 주 만에 80억 달러 아래로 떨어졌어요.\n같은 해 12월 사우디 국영 석유회사 **아람코**가 약 256억 달러를 모아 세계 최대 상장 기록을 새로 썼어요.",
      w: "비상장 기업가치는 투자자 몇 명이 합의한 숫자일 뿐이에요. 공시(S-1)가 그 숫자를 시험해요." },
    { y: "2020~21", t: "제로금리와 돈의 홍수", wk: "GameStop_short_squeeze", co: ["게임스톱", "로빈후드", "코인베이스", "리비안", "쿠팡", "스팩(SPAC)들"],
      toon: [["📱", "집에 갇혀 있고 지원금은 들어왔고… 주식 앱이나 깔아 볼까?"], ["🚀", "차를 몇 대 팔지도 않은 전기차 회사가 포드보다 비싸다고?"]],
      b: "코로나에 맞서 금리가 0이 되고 지원금이 풀리자 돈이 자산으로 몰렸어요.\n2021년 1월 개인 투자자들이 온라인에서 뭉쳐 **게임스톱** 주가를 몇 주 만에 20배 가까이 올렸어요. 껍데기 회사와 합쳐 상장하는 **스팩**이 2021년 한 해 600건 넘게 상장했어요.\n쿠팡(3월), 코인베이스(4월 직상장), 전기 트럭 회사 **리비안**(11월, 약 120억 달러 조달)이 줄줄이 상장했어요. 2021년 전 세계 벤처 투자는 6,000억 달러를 넘어 전해의 거의 두 배였어요.",
      w: "이때 매겨진 높은 기업가치가 이듬해부터 '다운 라운드', 감원, 상장 연기로 돌아왔어요." },
    { y: "2022", t: "금리가 오르자 모든 값이 내렸다", wk: "Federal_Reserve", co: ["미국 연준", "트위터", "FTX", "클라르나", "메타"],
      toon: [["🏦", "물가가 40년 만에 최고예요. 금리를 올립니다. 계속."], ["🥶", "작년엔 서로 투자하겠다더니 올해는 전화도 안 받네."]],
      b: "미국 연준은 2022년 3월부터 금리를 0에서 연말 4%대까지 올렸어요. 그해 나스닥은 약 33% 떨어졌어요.\n4월 일론 머스크가 **트위터**를 440억 달러에 사겠다고 했다가 물러서려 했고, 소송 끝에 10월 인수를 마쳤어요. 스웨덴 **클라르나**는 기업가치가 456억 달러에서 67억 달러로 깎여 투자받았어요.\n11월에는 기업가치 320억 달러였던 코인 거래소 **FTX**가 고객 돈을 빼돌린 사실이 드러나 며칠 만에 파산했어요.",
      w: "'투자 혹한기'의 시작. 금리가 투자 기사의 배경이라는 것을 모두가 배운 해예요." },
    { y: "2023", t: "은행이 무너지고, 가장 큰 게임 인수가 끝나다", wk: "Collapse_of_Silicon_Valley_Bank", co: ["실리콘밸리은행(SVB)", "크레디트스위스", "UBS", "마이크로소프트", "액티비전 블리자드"],
      toon: [["📲", "SVB가 위험하대. 지금 당장 돈 빼! (단체 채팅방)"], ["🎮", "687억 달러짜리 인수, 세 나라 당국 허락받는 데 21개월 걸렸어요."]],
      b: "스타트업들의 은행 **실리콘밸리은행**은 예금으로 산 채권 값이 금리 인상으로 떨어져 손실을 봤어요. 소문이 퍼지자 하루에 420억 달러가 빠져나갔고 2023년 3월 10일 문을 닫았어요.\n열흘 뒤 167년 된 스위스 **크레디트스위스**가 경쟁사 UBS에 30억 스위스프랑에 팔렸어요.\n10월에는 **마이크로소프트**가 게임 회사 액티비전 블리자드를 687억 달러에 사는 거래를 마쳤어요. 미국·영국·EU 당국의 반독점 심사를 넘는 데 21개월이 걸렸어요.",
      w: "큰 인수는 '계약'이 끝이 아니라 '당국 승인'이 끝이에요. 이 앱이 본계약과 종결을 구분하는 이유." },
    { y: "2023~", t: "AI로 다시 몰리는 돈", wk: "Nvidia", co: ["오픈AI", "마이크로소프트", "엔비디아", "앤트로픽", "구글", "아마존", "메타"],
      toon: [["🤖", "챗GPT, 두 달 만에 쓰는 사람이 1억 명."], ["⚡", "칩도 모자라고 전기도 모자라요. 데이터센터를 더 지읍시다."]],
      b: "2022년 11월 **오픈AI**가 챗GPT를 내놓자 판이 바뀌었어요. 2023년 1월 **마이크로소프트**가 오픈AI에 약 100억 달러를 넣는다고 보도됐어요.\nAI를 돌리는 칩을 만드는 **엔비디아**의 시가총액은 2023년 5월 1조 달러, 2024년 6월 3조 달러를 넘었어요. 아마존과 구글은 **앤트로픽**에 수십억 달러씩 투자했어요.\n벤처 투자 전체는 줄었는데 AI 회사 몇 곳이 그 돈의 큰 몫을 가져갔어요. 빅테크는 데이터센터에 해마다 수백억 달러를 쓰고 있어요.",
      w: "지금 딜 기사의 큰 몫이 AI인 이유. 철도·닷컴 때와 같은 질문이에요 — 거품인가, 시작인가. 아마 둘 다일 거예요." },
    { y: "정리", t: "400년 동안 되풀이된 다섯 가지", co: [],
      toon: [["🔁", "이번엔 다르다고요?"], ["📚", "그 말도 매번 나왔어요."]],
      b: "① **새 기술이 나오면 돈이 몰려요.** 향신료 항로, 철도, 라디오, 인터넷, AI.\n② **돈이 싸면(금리가 낮으면) 값이 부풀어요.** 1920년대, 1980년대 일본, 2021년.\n③ **거품은 터지지만 기술과 시설은 남아요.** 철도, 광케이블, 그리고 살아남은 회사들.\n④ **무너진 뒤에 규칙이 생겨요.** 1720년, 1934년 SEC, 2002년 회계법.\n⑤ **수익은 극소수에서 나와요.** DEC, 구글, 알리바바 같은 한 건이 나머지를 다 덮어요.\n기사를 볼 때 '지금은 이 다섯 중 어디쯤인가'를 물어보세요.",
      w: "이 다섯 가지가 머리에 있으면 처음 보는 기사도 어느 서랍에 넣을지 알게 돼요." } ] },

  { id: "us", flag: "🇺🇸", name: "미국", intro: "월스트리트와 실리콘밸리. 벤처캐피털과 사모펀드의 규칙은 거의 다 여기서 만들어졌어요. JP모건, 페어차일드, 애플, KKR, 넷스케이프, 구글, 페이스북이 차례로 나와요.", items: [
    { y: "1792", t: "버즘나무 아래의 약속", wk: "Buttonwood_Agreement", co: ["뉴욕증권거래소", "뱅크오브뉴욕"],
      toon: [["🌳", "우리끼리만 거래하고, 수수료는 0.25% 밑으로 안 깎기!"], ["✍️", "24명이 서명했지."]],
      b: "독립한 미국 정부가 전쟁 빚을 갚으려고 채권을 찍자 뉴욕 월가에서 그걸 사고파는 사람들이 생겼어요.\n1792년 중개인 24명이 버즘나무 아래에서 '서로만 거래하고 수수료를 정해 받자'고 약속했어요. **뉴욕증권거래소**의 뿌리예요.\n처음 거래된 주식 가운데 하나가 알렉산더 해밀턴이 세운 **뱅크오브뉴욕**이었어요.",
      w: "'월가(Wall Street)'가 금융의 대명사가 된 출발점." },
    { y: "1869~1901", t: "철도 재벌, JP모건, US스틸", wk: "U.S._Steel", co: ["JP모건", "카네기 철강", "US스틸", "유니언 퍼시픽", "골드만삭스(1869 설립)"],
      toon: [["🚂", "철도 회사들이 서로 값을 깎다 다 망하게 생겼소."], ["🎩", "내가 다 사서 하나로 합치겠소. — JP모건"]],
      b: "대륙횡단철도(1869)를 깔려고 유럽 돈이 미국으로 건너왔어요. 그 돈을 끌어온 은행가가 **JP모건**이에요. 망해 가는 철도 회사들을 사서 합치고 이사회에 자기 사람을 앉혔어요. 이것을 '모건화'라고 불렀어요.\n1901년 모건은 앤드루 카네기에게 4억 8천만 달러를 주고 철강회사를 사서 다른 회사들과 합쳤어요. **US스틸**, 자본금 14억 달러로 세계 첫 '10억 달러 기업'이었어요.\n1907년 금융 공황 때는 모건이 은행가들을 서재에 가둬 놓고 구제 자금을 모았어요. 한 사람에게 기댈 수 없다는 반성에서 1913년 중앙은행 **연준**이 생겼어요.",
      w: "금융이 산업을 사서 합치는 '롤업'의 원형. 지금 사모펀드가 같은 업종 회사를 여럿 사서 합치는 것과 같은 수법이에요." },
    { y: "1929~34", t: "대폭락과 새 규칙", wk: "U.S._Securities_and_Exchange_Commission", co: ["SEC", "JP모건", "모건스탠리", "골드만삭스"],
      toon: [["🧑‍⚖️", "예금 받는 은행과 주식 파는 은행을 갈라놓겠소."], ["✂️", "그래서 JP모건에서 모건스탠리가 갈라져 나왔어요."]],
      b: "1929년 주가 폭락 뒤 조사해 보니 은행들이 예금자 돈으로 주식 투기를 하고, 부실 주식을 고객에게 떠넘기고 있었어요.\n1933년 글래스-스티걸법이 **예금 은행과 투자은행을 갈라놓았어요**. JP모건은 예금 은행으로 남고, 주식·채권 일을 하던 사람들이 나가 **모건스탠리**(1935)를 세웠어요.\n1934년 **SEC**가 생겼어요. 초대 위원장은 주가 조작으로 돈을 번 조지프 케네디(케네디 대통령의 아버지)였어요. '도둑을 잡으려면 도둑을 써라'는 말이 나왔어요.",
      w: "이 장벽은 1999년에 없어졌고, 2008년 위기 뒤 다시 논쟁이 됐어요. 투자은행 이름들의 족보가 여기서 나와요." },
    { y: "1946~58", t: "벤처캐피털의 탄생", wk: "Georges_Doriot", co: ["ARDC", "DEC", "드레이퍼 게이더 앤더슨", "중소기업투자회사(SBIC)"],
      toon: [["🎖️", "전쟁 때 만든 기술, 누가 회사로 키우나?"], ["🧪", "7만 달러가 3억 5천만 달러가 됐어요."]],
      b: "군수 책임자였던 하버드 교수 조르주 도리오가 1946년 **ARDC**를 세웠어요. 부자 가문의 돈이 아니라 대학·보험사의 돈을 모아 기술 회사 지분을 산 첫 회사예요.\n1957년 **DEC**에 넣은 7만 달러는 1968년 상장 뒤 약 3억 5천만 달러 가치가 됐어요.\n1958년 정부는 민간 투자 회사에 싼 돈을 빌려주는 SBIC 제도를 만들었어요. 이듬해 서부에서 지금과 같은 '펀드' 방식(출자자와 운용사)의 첫 벤처 회사가 나왔어요.",
      w: "'남의 돈을 모아, 지분을 사고, 대박 하나로 번다'. 지금 VC의 세 가지 뼈대가 이때 갖춰졌어요." },
    { y: "1957~68", t: "페어차일드에서 인텔로", wk: "Traitorous_eight", co: ["쇼클리 반도체", "페어차일드 반도체", "인텔", "아서 록", "셔먼 페어차일드"],
      toon: [["🧑‍🔬", "여덟 명이 한꺼번에 사표를 냈다고? 배신자들!"], ["📝", "인텔 투자 설명서는 한 장 반. 이틀 만에 250만 달러가 모였어요."]],
      b: "1957년 쇼클리 연구소를 나온 여덟 명은 일할 회사를 찾다가, 투자은행 직원 아서 록의 권유로 직접 회사를 세웠어요. 돈은 카메라 회사 주인 셔먼 페어차일드가 댔어요. **페어차일드 반도체**예요.\n하지만 본사가 이익을 가져가고 기술자들에게 주식을 주지 않았어요. 사람들은 떠났어요.\n1968년 로버트 노이스와 고든 무어가 나와 **인텔**을 세웠어요. 아서 록이 쓴 한 장 반짜리 설명서로 이틀 만에 250만 달러가 모였어요. 이번에는 직원 모두에게 주식을 나눠 줬어요.",
      w: "'기술자에게 주식을 준다'는 실리콘밸리 문화가 페어차일드의 실패에서 나왔어요. 스톡옵션의 뿌리." },
    { y: "1972~80", t: "샌드힐로드, 애플, 제넨텍", wk: "Sand_Hill_Road", co: ["세쿼이아", "클라이너 퍼킨스", "애플", "제넨텍", "아타리"],
      toon: [["🍎", "차고의 두 청년에게 누가 투자하지?"], ["🧬", "유전자로 약을 만든다는 회사, 상장 첫날 주가가 두 배 넘게."]],
      b: "1972년 스탠퍼드 옆 샌드힐로드에 **세쿼이아**와 **클라이너 퍼킨스**가 문을 열었어요.\n세쿼이아의 돈 발렌타인은 게임 회사 아타리에 투자했다가 거기서 일하던 스티브 잡스를 알게 돼 1978년 **애플**에 투자했어요. 클라이너 퍼킨스는 1976년 바이오 회사 **제넨텍**에 넣었어요.\n1980년 두 회사가 나란히 상장했어요. 애플 상장으로 하루에 백만장자가 300명쯤 생겼다고 해요. 1979년 연기금의 벤처 투자가 풀린 것과 맞물려 돈이 쏟아져 들어왔어요.",
      w: "세쿼이아와 클라이너 퍼킨스는 지금도 기사에 나와요. 이 두 곳이 투자했다는 것 자체가 뉴스가 되는 이유." },
    { y: "1976~89", t: "KKR과 정크본드의 시대", wk: "Kohlberg_Kravis_Roberts", co: ["KKR", "베어스턴스", "드렉셀 번햄 램버트", "RJR 나비스코", "블랙스톤", "칼라일"],
      toon: [["👔", "베어스턴스에서 나온 세 사람이 12만 달러로 시작했어요."], ["🚬", "13년 뒤 250억 달러짜리 회사를 샀죠."]],
      b: "1976년 베어스턴스 출신 콜버그, 크래비스, 로버츠가 **KKR**을 세웠어요. 회사를 살 돈의 대부분을 빌리고, 산 회사가 버는 돈으로 갚는 방식이었어요.\n드렉셀의 마이클 밀켄이 신용이 낮은 회사의 채권(정크본드)을 대량으로 팔아 주면서 빌릴 수 있는 돈이 엄청나게 커졌어요.\n1985년 **블랙스톤**, 1987년 **칼라일**이 생겼어요. 1988년 KKR이 **RJR 나비스코**를 약 250억 달러에 샀어요. 1990년 밀켄은 증권법 위반으로 감옥에 갔고 드렉셀은 파산했어요.",
      w: "세계 3대 사모펀드가 모두 이 10년에 태어났어요. '빚으로 사서 고쳐 판다'는 지금도 같아요." },
    { y: "1995~2000", t: "넷스케이프에서 닷컴 붕괴까지", wk: "Netscape", co: ["넷스케이프", "아마존", "이베이", "야후", "시스코", "펫츠닷컴", "웹밴", "AOL·타임워너"],
      toon: [["🧑‍💻", "24살이 만든 브라우저 회사, 상장 첫날 시가총액 29억 달러."], ["🛒", "식료품 배달 웹밴은 8억 달러를 쓰고 2년 만에 파산."]],
      b: "1995년 8월 **넷스케이프** 상장이 신호탄이었어요. 클라이너 퍼킨스가 투자한 회사였고, 같은 회사가 **아마존**(1997 상장)에도 일찍 들어갔어요.\n1999년 한 해 미국에서 400개가 넘는 회사가 상장했고 상당수가 첫날 주가가 두 배가 됐어요. 인터넷 장비를 파는 **시스코**는 2000년 3월 세계에서 가장 비싼 회사가 됐어요.\n그달 나스닥이 꺾였어요. 펫츠닷컴, 웹밴 같은 회사가 줄줄이 사라졌고, 5조 달러의 시가총액이 증발했어요.",
      w: "아마존 주가는 90% 넘게 떨어졌다가 살아남았어요. 거품 속에서도 진짜는 있고, 진짜도 한동안은 같이 떨어져요." },
    { y: "2004~12", t: "구글, 페이스북, 그리고 '소프트웨어가 세상을 먹는다'", wk: "Y_Combinator", co: ["구글", "페이스북", "와이콤비네이터", "앤드리슨 호로위츠", "유튜브", "인스타그램", "에어비앤비", "드롭박스"],
      toon: [["🎓", "석 달 동안 가르치고 2만 달러 줄게. 지분 6%만. — 와이콤비네이터"], ["📸", "직원 13명 회사를 10억 달러에? 미쳤군. (10년 뒤: 싸게 샀네.)"]],
      b: "2004년 **구글**이 상장했고, 같은 해 하버드 기숙사에서 **페이스북**이 시작됐어요. 2005년 초기 창업자를 뽑아 가르치는 **와이콤비네이터**가 문을 열어 에어비앤비, 드롭박스, 스트라이프를 길러 냈어요.\n구글은 2006년 **유튜브**를 16.5억 달러에 샀어요. 2009년 넷스케이프 창업자가 만든 **앤드리슨 호로위츠**는 '소프트웨어가 세상을 먹어 치운다'며 큰돈을 걸었어요.\n2012년 페이스북은 **인스타그램**을 10억 달러에 사고 한 달 뒤 기업가치 1,040억 달러로 상장했어요.",
      w: "빅테크가 '위협이 될 회사를 일찍 산다'는 전략이 이때 자리 잡았고, 지금의 반독점 논쟁으로 이어져요." },
    { y: "2008", t: "월가의 일주일", wk: "Lehman_Brothers", co: ["리먼브러더스", "베어스턴스", "메릴린치", "AIG", "골드만삭스", "모건스탠리", "워런 버핏(버크셔 해서웨이)"],
      toon: [["📞", "일요일 밤 재무장관 전화: '리먼은 못 구합니다.'"], ["🧓", "버핏: 골드만에 50억 달러 넣지. 대신 이자는 10%."]],
      b: "2008년 9월 둘째 주말, 재무장관과 은행장들이 뉴욕 연준 건물에 모였지만 **리먼브러더스**를 살 곳을 찾지 못했어요. 월요일 새벽 리먼은 파산을 신청했어요.\n같은 날 **메릴린치**는 뱅크오브아메리카에 팔렸고, 이틀 뒤 정부가 보험사 **AIG**를 구했어요.\n마지막 남은 두 투자은행 **골드만삭스**와 **모건스탠리**는 일주일 뒤 예금 은행 지주회사로 바뀌었어요. 워런 버핏이 골드만에 50억 달러를 넣어 믿음을 보탰어요. 월가의 '독립 투자은행' 시대가 끝났어요.",
      w: "위기 때 돈을 가진 사람이 가장 좋은 조건을 받아요. 버핏의 그 거래는 지금도 교과서에 나와요." },
    { y: "2012~19", t: "유니콘과 '오래 비상장으로'", wk: "Uber", co: ["우버", "에어비앤비", "스페이스X", "스트라이프", "타이거글로벌", "소프트뱅크", "위워크"],
      toon: [["🦄", "상장? 왜 해요. 비상장으로도 수십억 달러가 들어오는데."], ["🧾", "그러다 상장 서류를 내자 숫자가 다 드러났죠."]],
      b: "금리가 낮아 돈이 넘치자 헤지펀드, 뮤추얼펀드, 국부펀드까지 비상장 회사에 직접 투자했어요. 회사들은 상장을 미뤘어요.\n**우버**는 상장 전까지 200억 달러 넘게 투자받았어요. 아마존이 창업 3년 만에 상장한 것과 달리 우버는 10년 걸렸어요(2019).\n2019년 우버 상장은 첫날 주가가 떨어졌고, **위워크**는 상장 자체가 무산됐어요. '성장만 하면 된다'는 믿음에 금이 갔어요.",
      w: "비상장 회사에 오래 머물면 일반 투자자는 가장 크게 오르는 구간에 참여할 수 없어요. 요즘 '비상장 주식 거래' 기사가 느는 배경." },
    { y: "2020~21", t: "스팩, 밈 주식, 사상 최대의 해", wk: "Special-purpose_acquisition_company", co: ["로빈후드", "게임스톱", "스노우플레이크", "에어비앤비", "리비안", "코인베이스", "타이거글로벌"],
      toon: [["🎰", "유명인이 스팩을 만들고, 스팩이 로켓 회사를 사고…"], ["🐯", "타이거글로벌은 2021년에 하루 한 건 넘게 투자했어요."]],
      b: "2020년 말 **에어비앤비**가 상장 첫날 두 배가 됐어요. 2021년 미국에서 약 1,000건이 상장했고 그 가운데 600건 넘는 것이 **스팩**이었어요.\n헤지펀드 **타이거글로벌**은 실사를 며칠 만에 끝내고 높은 값을 불러 2021년 300건 넘게 투자했어요. 다른 VC들도 속도를 따라갔어요.\n2021년 미국 벤처 투자는 약 3,300억 달러로 전해의 두 배였어요.",
      w: "이때 투자받은 회사들이 2023~25년에 '값을 깎아 투자받거나, 팔리거나, 문을 닫는' 기사로 돌아와요." },
    { y: "2022~23", t: "혹한기와 실리콘밸리은행", wk: "Silicon_Valley_Bank", co: ["실리콘밸리은행(SVB)", "퍼스트리퍼블릭", "JP모건", "메타", "아마존"],
      toon: [["✂️", "빅테크도 감원. 메타 1만 1천 명, 아마존 1만 8천 명."], ["🏃", "40년 된 은행이 36시간 만에 무너졌어요."]],
      b: "금리가 오르자 상장이 멈췄어요. 2022년 미국 상장으로 모은 돈은 전해의 10분의 1도 안 됐어요. 빅테크가 처음으로 대규모 감원을 했어요.\n2023년 3월 스타트업 절반이 거래하던 **실리콘밸리은행**이 무너졌어요. 유명 VC들이 투자한 회사들에 '돈을 빼라'고 알리자 하루에 420억 달러가 빠져나갔어요. 정부가 예금 전액을 보장해 번지는 것을 막았어요.\n5월에는 **퍼스트리퍼블릭**이 무너져 JP모건에 팔렸어요.",
      w: "스마트폰과 단체 채팅방 시대의 뱅크런은 며칠이 아니라 몇 시간이에요." },
    { y: "2023~", t: "AI: 한 줌의 회사로 몰리는 돈", wk: "OpenAI", co: ["오픈AI", "마이크로소프트", "엔비디아", "앤트로픽", "아마존", "구글", "xAI", "코어위브"],
      toon: [["🧠", "AI 회사 몇 곳이 벤처 투자금의 큰 몫을 가져가요."], ["🔌", "칩을 사려고 빚을 내고, 그 칩을 담보로 또 빚을 내요."]],
      b: "챗GPT 뒤 벤처 돈의 흐름이 바뀌었어요. 전체 투자 건수는 줄었는데 **오픈AI**, **앤트로픽**, xAI 같은 몇 곳이 한 번에 수십억~수백억 달러를 받았어요.\n돈을 대는 쪽도 달라졌어요. VC가 아니라 **마이크로소프트**, 아마존, 구글, 엔비디아 같은 큰 회사들이 넣고, 그 돈은 다시 그 회사들의 클라우드와 칩을 사는 데 쓰여요.\nAI 칩을 빌려주는 **코어위브**는 엔비디아 칩을 담보로 큰 빚을 내 2025년 상장했어요.",
      w: "'투자한 돈이 다시 투자자의 매출이 된다'는 순환 구조가 건강한지가 요즘 가장 큰 논쟁거리예요." } ] },
  { id: "eu", flag: "🇪🇺", name: "유럽", intro: "주식회사와 거래소와 거품이 태어난 곳. 지금은 미국보다 판이 작지만 사모펀드·규제·명품과 제약의 힘이 세요. 로스차일드, 보다폰, 스카이프, ARM, 스포티파이, LVMH가 나와요.", items: [
    { y: "1602~11", t: "암스테르담, 첫 거래소와 첫 공매도", wk: "Amsterdam_Stock_Exchange", co: ["네덜란드 동인도회사", "암스테르담 거래소", "암스테르담 은행"],
      toon: [["🏛️", "주식을 사고팔 건물을 따로 지읍시다."], ["🐻", "나는 주가가 떨어지는 쪽에 걸겠네. — 첫 공매도꾼 이삭 르 메르"]],
      b: "동인도회사 주식 거래가 늘자 1611년 암스테르담에 거래소 건물이 지어졌어요.\n벌써 요즘 같은 일이 벌어졌어요. 회사에서 쫓겨난 창립 주주 이삭 르 메르는 1609년 주식을 빌려 팔고 나쁜 소문을 퍼뜨려 값을 떨어뜨리려 했어요. 역사에 남은 **첫 공매도**예요. 정부는 이듬해 공매도를 금지했어요.\n선물, 옵션 거래도 이때 이미 있었어요.",
      w: "공매도 금지, 주가 조작 처벌 같은 요즘 논쟁은 400년 전에도 똑같이 있었어요." },
    { y: "1815~75", t: "로스차일드, 국경을 넘는 은행", wk: "Waddesdon_Manor", co: ["로스차일드 은행", "수에즈 운하 회사", "영국 정부"],
      toon: [["🕊️", "다섯 형제가 다섯 도시에. 편지는 비둘기와 전령으로."], ["🚢", "총리님, 수에즈 운하 주식 살 400만 파운드요? 내일 드리죠."]],
      b: "프랑크푸르트 출신 로스차일드 가문의 다섯 형제가 프랑크푸르트·런던·파리·빈·나폴리에 은행을 열었어요. 형제끼리 정보와 돈을 빠르게 주고받아 나라들의 전쟁 채권과 철도에 돈을 댔어요.\n1875년 영국 총리 디즈레일리가 이집트가 내놓은 **수에즈 운하** 주식을 급히 사려 할 때, 의회 승인을 기다릴 수 없어 로스차일드에게 400만 파운드를 빌렸어요. 하루 만에 마련됐어요.",
      w: "지금도 로스차일드는 인수합병 자문사로 기사에 나와요. 국경을 넘는 금융의 원형이에요." },
    { y: "1855~1900", t: "유한책임과 독일의 '은행이 주인인' 산업", wk: "Deutsche_Bank", co: ["도이체방크(1870)", "지멘스", "바스프", "크레디 모빌리에"],
      toon: [["🇬🇧", "영국: 주식시장에서 돈을 모읍시다."], ["🇩🇪", "독일: 은행이 직접 빌려주고 이사회에 앉겠소."]],
      b: "영국이 유한책임(1855)으로 주식시장을 키울 때, 뒤늦게 산업화한 독일은 다른 길을 갔어요.\n1870년 세워진 **도이체방크** 같은 큰 은행이 지멘스, 바스프 같은 회사에 돈을 빌려주고 지분도 갖고 이사회에도 앉았어요. 회사와 은행이 오래 묶였어요.\n이 방식은 뒤에 일본과 한국이 본떴어요.",
      w: "영미식(주식시장 중심)과 독일·일본식(은행 중심). 나라마다 '회사의 주인이 누구냐'가 다른 뿌리예요." },
    { y: "1945~80", t: "국유화의 시대, 그리고 3i", wk: "3i", co: ["3i(1945)", "르노", "브리티시 스틸", "폴크스바겐"],
      toon: [["🏭", "전쟁으로 다 부서졌으니 나라가 맡아 다시 짓자."], ["🌱", "작은 회사에 돈 대 줄 곳도 하나 만듭시다. — 3i"]],
      b: "전쟁 뒤 영국과 프랑스는 석탄, 철강, 철도, 자동차(르노)를 나라 것으로 만들었어요.\n같은 1945년 영국은 은행들이 돈을 모아 중소기업에 오래 투자하는 회사를 세웠어요. 지금의 **3i**, 유럽 사모펀드·벤처의 조상이에요.\n주식시장은 작았고 회사 돈줄은 은행과 나라였어요.",
      w: "이때 나라 것이 된 회사들이 1980년대에 다시 팔리면서 유럽 주식시장이 커져요." },
    { y: "1979~90", t: "대처의 민영화와 런던 빅뱅", wk: "Big_Bang_(financial_markets)", co: ["브리티시 텔레콤", "브리티시 가스", "브리티시 항공", "런던증권거래소", "SG 워버그"],
      toon: [["📺", "'시드에게 알려 줘!' 가스 회사 주식 광고가 TV에 나왔어요."], ["💥", "1986년 10월 27일, 런던 금융가 규제가 하루에 풀렸죠."]],
      b: "대처 정부는 나라 회사를 주식으로 팔았어요. 1984년 **브리티시 텔레콤**, 1986년 **브리티시 가스**. TV 광고까지 해서 보통 사람 수백만 명이 처음 주식을 샀어요.\n1986년 10월 27일 '**빅뱅**'으로 고정 수수료를 없애고 외국 회사에 문을 열고 전자 거래를 들였어요. 미국·일본·스위스 은행들이 런던의 오래된 증권사들을 사들였어요.\n런던은 유럽 금융의 수도가 됐고, 프랑스·독일·이탈리아도 민영화를 따라 했어요.",
      w: "'민영화'와 '국민주'의 원조. 한국의 포항제철·한국전력 국민주(1988~89)도 이것을 본떴어요." },
    { y: "1999~2000", t: "유로, 그리고 사상 최대의 적대적 인수", wk: "Mannesmann", co: ["보다폰", "만네스만", "유럽중앙은행", "오렌지"],
      toon: [["📱", "영국 회사가 독일의 자존심을 삼킨다고? 절대 안 돼!"], ["💶", "석 달 뒤, 주주들이 1,800억 달러에 넘어갔어요."]],
      b: "1999년 1월 유로화가 생겨 국경을 넘는 거래가 쉬워졌어요.\n그해 11월 영국 통신사 **보다폰**이 109년 된 독일 기업 **만네스만**을 사겠다고 나섰어요. 경영진과 노조, 독일 총리까지 반대했지만 보다폰은 주주들에게 직접 값을 올려 불렀어요. 2000년 2월 약 1,800억 달러에 성사됐어요. 지금도 손꼽히는 사상 최대 인수예요.\n독일에서 외국 회사의 적대적 인수가 성공한 첫 사례였어요.",
      w: "'주주가 판다고 하면 팔린다'가 유럽 대륙에도 통하게 된 사건. 닷컴 거품 꼭대기의 값이기도 했어요." },
    { y: "2003~11", t: "스카이프와 유럽 스타트업의 씨앗", wk: "Skype", co: ["스카이프", "이베이", "마이크로소프트", "아토미코", "인덱스 벤처스", "실버레이크"],
      toon: [["🎧", "에스토니아 개발자 넷이 만든 공짜 전화."], ["🔁", "이베이 26억 달러 → 사모펀드 → 마이크로소프트 85억 달러."]],
      b: "스웨덴·덴마크 창업자와 에스토니아 개발자들이 만든 **스카이프**는 2005년 이베이에 26억 달러에 팔렸어요.\n이베이는 쓸 곳을 못 찾아 2009년 사모펀드 실버레이크 등에 지분을 넘겼고, 2011년 **마이크로소프트**가 85억 달러에 샀어요.\n창업자 니클라스 젠스트롬은 번 돈으로 벤처 회사 **아토미코**를 세웠고, 스카이프 출신들이 와이즈(송금), 볼트(차량 호출)를 만들었어요. 인구 130만의 에스토니아가 유니콘의 나라가 된 까닭이에요.",
      w: "큰 회수 한 번이 다음 세대를 낳는 무늬. 같은 회사가 세 번 팔리며 값이 달라지는 것도 눈여겨보세요." },
    { y: "2010~12", t: "유로존 위기", wk: "European_debt_crisis", co: ["유럽중앙은행", "IMF", "그리스 정부", "도이체방크", "방키아"],
      toon: [["🏛️", "그리스 재정 적자가 발표한 것의 두 배였다고요?"], ["🛡️", "유로를 지키기 위해 무엇이든 하겠습니다. — 드라기 총재"]],
      b: "2009년 그리스가 재정 적자를 숨겨 왔다고 밝히자 남유럽 국채 값이 무너졌어요. 그리스, 아일랜드, 포르투갈이 구제금융을 받았고 스페인 은행 **방키아**는 나라가 떠안았어요.\n2012년 7월 유럽중앙은행 총재 마리오 드라기가 '무엇이든 하겠다'고 말하자 시장이 가라앉았어요. 말 한마디가 수백조 원의 효과를 냈어요.\n유럽 은행들은 그 뒤 10년 넘게 미국 은행에 뒤처졌어요.",
      w: "유럽 은행 주가가 왜 오래 쌌는지, 유럽 스타트업이 왜 미국 돈에 기대는지의 배경." },
    { y: "2016~18", t: "ARM과 스포티파이: 유럽 기술 회사의 두 길", wk: "Arm_Holdings", co: ["ARM", "소프트뱅크", "스포티파이", "아디옌", "뉴욕증권거래소"],
      toon: [["🧩", "스마트폰 칩 설계의 95%를 쥔 영국 회사, 일본에 팔렸어요."], ["🎵", "스웨덴 음악 앱은 주관사 없이 뉴욕에 바로 상장."]],
      b: "브렉시트 투표 한 달 뒤인 2016년 7월, 소프트뱅크가 영국 케임브리지의 칩 설계 회사 **ARM**을 약 243억 파운드에 샀어요. 파운드 값이 떨어진 틈이었어요.\n2018년 스웨덴 **스포티파이**는 새 주식을 찍지 않는 직상장으로 뉴욕에 올랐어요. 같은 해 네덜란드 결제 회사 **아디옌**은 암스테르담에 상장해 첫날 두 배가 됐어요.\nARM은 2023년 런던이 아니라 나스닥에 다시 상장했어요.",
      w: "유럽에서 큰 기술 회사는 '외국에 팔리거나 미국에 상장한다'. 유럽이 가장 아파하는 지점이에요." },
    { y: "2019~21", t: "LVMH와 티파니, 그리고 유럽의 진짜 강자", wk: "LVMH", co: ["LVMH", "티파니", "에르메스", "ASML", "노보 노디스크", "EQT"],
      toon: [["💎", "코로나가 왔으니 값을 깎읍시다. 아니면 안 삽니다."], ["⚖️", "소송 끝에 4억 달러쯤 깎아 158억 달러에."]],
      b: "유럽에서 가장 비싼 회사들은 기술 회사가 아니라 명품(**LVMH**, 에르메스), 반도체 장비(**ASML**), 제약(**노보 노디스크**)이에요.\n2019년 LVMH가 미국 보석 회사 **티파니**를 162억 달러에 사기로 했다가 코로나가 터지자 물러서려 했어요. 서로 소송을 건 끝에 값을 조금 깎아 2021년 1월 약 158억 달러에 마쳤어요.\n스웨덴 사모펀드 **EQT**는 2019년 상장해 유럽에서 가장 큰 사모펀드 운용사 가운데 하나가 됐어요.",
      w: "계약 뒤에도 상황이 바뀌면 값을 다시 흥정해요. '중대한 악화(MAC) 조항' 다툼의 대표 사례." },
    { y: "2021~23", t: "클라르나의 롤러코스터와 크레디트스위스의 끝", wk: "Klarna", co: ["클라르나", "세쿼이아", "소프트뱅크", "크레디트스위스", "UBS", "아르케고스", "그린실"],
      toon: [["🛍️", "456억 달러 → 67억 달러. 1년 만에 85%가 깎였어요."], ["🇨🇭", "167년 된 은행을 주말 사이에 경쟁사에 넘겼죠."]],
      b: "스웨덴 후불결제 **클라르나**는 2021년 소프트뱅크 투자로 기업가치 456억 달러, 유럽에서 가장 비싼 스타트업이 됐어요. 2022년 7월 67억 달러로 깎여 투자받았어요. 2025년 뉴욕에 상장했어요.\n스위스 **크레디트스위스**는 2021년 아르케고스와 그린실 사태로 큰 손실을 본 뒤 믿음을 잃었어요. 2023년 3월 예금이 빠져나가자 스위스 정부가 주말 사이에 **UBS**에 30억 스위스프랑에 넘겼어요.",
      w: "다운 라운드를 겪고도 살아남아 상장하는 회사가 있고, 믿음을 잃어 사라지는 은행이 있어요." },
    { y: "2023~", t: "AI 주권과 방위산업", wk: "Mistral_AI", co: ["미스트랄 AI", "ASML", "헬싱", "라인메탈", "딥마인드(구글)"],
      toon: [["🇫🇷", "미국·중국 AI에만 기댈 순 없어요. 우리 것도 있어야죠."], ["🛡️", "전쟁이 돌아오자 방산 스타트업에 돈이 몰려요."]],
      b: "2023년 파리에서 구글 딥마인드·메타 출신들이 **미스트랄 AI**를 세웠어요. 창업 한 달 만에 1억 유로 넘게 투자받았고, 뒤에 네덜란드 **ASML**이 큰 주주가 됐어요.\n우크라이나 전쟁 뒤에는 방위산업에 돈이 몰렸어요. 독일 **라인메탈** 주가는 몇 배가 됐고, AI 방산 스타트업 **헬싱**은 유럽에서 가장 비싼 스타트업 가운데 하나가 됐어요.\n유럽은 '규제는 잘하는데 큰 회사를 못 키운다'는 반성 속에 연기금 돈을 벤처로 돌리려 하고 있어요.",
      w: "유럽 딜 기사에 '주권(sovereign)', '방산', '전략적 자율'이 붙으면 이 흐름이에요." } ] },
  { id: "jp", flag: "🇯🇵", name: "일본", intro: "재벌과 은행의 나라에서 거품과 잃어버린 30년을 지나, 지금은 사모펀드와 주주가 회사를 흔드는 나라로. 미쓰비시, 소니, 소프트뱅크, 도시바, 세븐일레븐이 나와요.", items: [
    { y: "1878~1930", t: "거래소와 재벌(자이바쓰)", wk: "Zaibatsu", co: ["도쿄 주식거래소", "미쓰이", "미쓰비시", "스미토모", "야스다"],
      toon: [["⚓", "나라가 지은 조선소·광산을 싸게 넘겨받았지."], ["🏯", "은행, 상사, 공장을 한 가문이 다 쥐었어요."]],
      b: "메이지 정부는 1878년 도쿄에 주식거래소를 열고, 나라가 지은 공장과 광산을 몇몇 상인 가문에 싸게 넘겼어요.\n미쓰이, **미쓰비시**(이와사키 가문), 스미토모, 야스다. 가문의 지주회사가 은행·상사·중공업을 거느리는 **자이바쓰(재벌)**가 됐어요.\n1930년대에는 네 재벌이 일본 회사 자본의 4분의 1쯤을 쥐었어요.",
      w: "한국 '재벌'이라는 낱말이 같은 한자(財閥)예요. 구조도 여기서 건너왔어요." },
    { y: "1945~70", t: "재벌 해체, 그리고 '계열'로 다시 묶이다", wk: "Keiretsu", co: ["미쓰비시 은행", "미쓰이 물산", "도요타", "소니(1946)", "혼다(1948)"],
      toon: [["🇺🇸", "미군정: 재벌 가문의 주식을 다 내놓으시오."], ["🤝", "그럼 우리끼리 서로 주식을 들어 줍시다. 아무도 못 사게."]],
      b: "미군정은 재벌 가문의 지주회사를 없애고 주식을 팔게 했어요.\n하지만 1950년대부터 옛 재벌 회사들이 **은행을 가운데 두고 서로 주식을 들어 주는** 방식으로 다시 묶였어요. 이것이 '계열(게이레쓰)'이에요. 주식의 절반 넘게가 이런 '우호 주주' 손에 있어 외부인이 회사를 살 수 없었어요.\n그 바깥에서 재벌이 아닌 회사들이 자랐어요. **소니**(1946)와 **혼다**(1948)예요.",
      w: "요즘 일본 기사의 '정책 보유 주식(서로 들고 있는 주식) 매각'이 이 묶음을 푸는 일이에요." },
    { y: "1985~89", t: "플라자 합의와 거품", wk: "Plaza_Accord", co: ["일본은행", "노무라증권", "NTT", "미쓰비시지쇼", "소니"],
      toon: [["💴", "엔화가 2년 만에 두 배. 수출이 죽겠다, 금리를 내리자!"], ["🏯", "황궁 땅값이 캘리포니아 전체보다 비싸다는 말이 돌았어요."]],
      b: "1985년 9월 뉴욕 플라자 호텔에서 미국·일본·서독·영국·프랑스가 달러 값을 내리기로 했어요. 엔화는 2년 만에 달러당 240엔에서 120엔대가 됐어요.\n수출을 걱정한 일본은행이 금리를 크게 내리자 돈이 주식과 땅으로 몰렸어요. 1987년 상장한 통신사 **NTT**는 한때 세계에서 가장 비싼 회사였고, **노무라증권**은 세계 최대 증권사였어요.\n1989년 말 세계 시가총액 상위 10개 회사 가운데 7개가 일본 회사였어요.",
      w: "'환율을 누르려고 금리를 내렸다가 거품이 생겼다'. 지금 각국 중앙은행이 가장 두려워하는 교훈이에요." },
    { y: "1990~2003", t: "붕괴와 은행 정리", wk: "Lost_Decades", co: ["야마이치증권", "일본장기신용은행", "리플우드", "신세이은행", "닛산", "르노"],
      toon: [["😭", "사원들은 잘못이 없습니다! — 야마이치증권 사장의 눈물"], ["🧹", "미국 사모펀드가 망한 은행을 사서 고쳐 팔았어요."]],
      b: "1990년부터 주가와 땅값이 무너졌어요. 은행들은 부실 대출을 숨기며 버티다가 1997년 100년 된 **야마이치증권**이 문을 닫았어요.\n1998년 나라가 떠안은 **일본장기신용은행**을 미국 사모펀드 **리플우드**가 2000년 약 10억 달러에 사서 **신세이은행**으로 고쳐 2004년 상장시켰어요. 큰 이익을 냈고 '벌처(독수리) 펀드'라는 비난도 받았어요.\n1999년 빚더미의 **닛산**은 프랑스 **르노**에 지분을 넘겼고, 카를로스 곤이 공장을 닫고 계열 거래를 끊어 살렸어요.",
      w: "한국의 론스타-외환은행과 꼭 닮은 이야기. 일본에서 외국계 사모펀드에 대한 경계심이 생긴 뿌리예요." },
    { y: "1994~2006", t: "소프트뱅크의 큰 베팅과 라이브도어 쇼크", wk: "SoftBank_Group", co: ["소프트뱅크", "야후", "야후재팬", "알리바바", "보다폰재팬", "라이브도어", "후지TV"],
      toon: [["🐟", "5분 만에 정했어요. 눈빛이 좋았거든. — 손정의, 마윈을 만나고"], ["👕", "티셔츠 입은 청년이 방송국을 사겠다고?"]],
      b: "손정의의 **소프트뱅크**는 1996년 미국 야후에 1억 달러를 넣어 최대 주주가 되고 야후재팬을 세웠어요. 2000년에는 **알리바바**에 2,000만 달러를 넣었어요. 닷컴 붕괴로 손정의의 재산은 99%가 날아갔지만 알리바바 지분은 남았어요. 2006년에는 **보다폰재팬**을 약 1.75조 엔에 사서 통신사가 됐어요.\n2005년 인터넷 회사 **라이브도어**의 호리에 다카후미가 후지TV 계열 방송사를 적대적으로 사려 했어요. 기성 재계가 뒤집혔고, 이듬해 그는 회계 부정으로 체포됐어요.",
      w: "일본에서 '적대적 인수'와 '젊은 창업자'가 오랫동안 나쁜 말이 된 사건. 그 분위기가 최근에야 바뀌고 있어요." },
    { y: "2014~15", t: "아베노믹스: 주주를 보라", wk: "Abenomics", co: ["일본 공적연금(GPIF)", "도쿄증권거래소", "일본은행", "화낙", "서드포인트"],
      toon: [["📜", "회사는 주주와 대화하고, 연기금은 목소리를 내시오."], ["💰", "세계 최대 연금이 주식 비중을 두 배로 늘렸어요."]],
      b: "아베 정부는 2014년 기관투자자 행동 규칙(스튜어드십 코드), 2015년 **기업지배구조 코드**를 만들었어요. 사외이사를 두고 서로 들고 있는 주식을 왜 들고 있는지 설명하라는 내용이에요.\n세계 최대 연금 **GPIF**는 주식 비중을 24%에서 50%로 늘렸어요. 일본은행은 주식 펀드(ETF)까지 사들였어요.\n미국 행동주의 펀드 서드포인트가 로봇 회사 **화낙**에 '쌓아 둔 현금을 주주에게 돌려주라'고 요구해 배당을 늘리게 했어요.",
      w: "일본 주식이 10년 넘게 오른 바닥 공사. '회사는 누구 것인가'의 답이 바뀌기 시작했어요." },
    { y: "2016~19", t: "ARM, 비전펀드, 그리고 다케다", wk: "SoftBank_Vision_Fund", co: ["소프트뱅크", "ARM", "비전펀드", "사우디 PIF", "우버", "위워크", "다케다", "샤이어"],
      toon: [["🔮", "나는 300년 계획이 있어요. — 손정의"], ["💊", "일본 제약사가 자기보다 큰 아일랜드 회사를 620억 달러에."]],
      b: "2016년 소프트뱅크는 **ARM**을 사고, 2017년 약 1,000억 달러 **비전펀드**를 만들었어요. 우버, 위워크, 쿠팡, 디디, 그랩에 수십억 달러씩 넣었어요.\n2018년 **다케다**는 희귀병 약 회사 **샤이어**를 약 620억 달러에 사기로 했어요. 일본 기업의 해외 인수로 사상 최대였고, 창업 가문 일부가 '빚이 너무 크다'며 반대했어요.\n2019년 위워크가 무너지자 비전펀드는 큰 손실을 냈어요.",
      w: "'안에서는 클 곳이 없으니 밖에서 산다'. 일본 대기업의 해외 인수는 지금도 딜 기사의 단골이에요." },
    { y: "2015~23", t: "도시바의 몰락", wk: "Toshiba", co: ["도시바", "웨스팅하우스", "베인캐피털", "SK하이닉스", "엘리엇", "JIP", "키옥시아"],
      toon: [["📉", "이익을 부풀렸고, 미국 원전 자회사는 파산했어요."], ["🔒", "148년 된 회사, 74년 만에 증시를 떠납니다."]],
      b: "2015년 **도시바**가 7년 동안 이익을 부풀린 것이 드러났어요. 2017년에는 미국 원전 자회사 **웨스팅하우스**가 파산해 큰 손실이 났어요.\n살아남으려고 알짜인 메모리 반도체 사업을 **베인캐피털** 연합(SK하이닉스 참여)에 약 2조 엔에 팔았어요. 지금의 **키옥시아**예요. 급히 증자를 하면서 엘리엇 같은 행동주의 펀드들이 큰 주주가 됐고, 경영진과 몇 해를 싸웠어요.\n2023년 일본 사모펀드 **JIP** 연합이 약 2조 엔에 사서 상장폐지했어요.",
      w: "회계 부정 → 사업 매각 → 행동주의 → 상장폐지. 요즘 일본 딜의 낱말이 이 한 회사에 다 들어 있어요." },
    { y: "2023", t: "'PBR 1배'와 버핏", wk: "Tokyo_Stock_Exchange", co: ["도쿄증권거래소", "버크셔 해서웨이", "미쓰비시상사", "이토추", "미쓰이물산", "스미토모상사", "마루베니"],
      toon: [["📣", "주가가 가진 재산보다 싼 회사는 대책을 내놓으시오."], ["🧓", "버핏: 일본 5대 상사 주식을 더 사겠습니다."]],
      b: "2023년 3월 **도쿄증권거래소**가 주가가 순자산보다 낮은(PBR 1배 미만) 회사들에 개선 계획을 내라고 했어요. 상장사 절반쯤이 해당됐어요. 회사들이 자사주를 사고 배당을 늘렸어요.\n**워런 버핏**은 2020년부터 일본 5대 종합상사 주식을 사 왔고, 2023년 도쿄를 찾아 더 사겠다고 했어요.\n외국인 돈이 몰려 2024년 2월 닛케이 지수가 34년 만에 최고치를 넘었어요.",
      w: "한국의 '밸류업 프로그램'(2024)이 이것을 본뜬 거예요. '코리아 디스카운트' 기사의 비교 대상이 일본이에요." },
    { y: "2023~25", t: "인수 제안을 거절할 수 없는 나라가 되다", wk: "Seven_&_i_Holdings", co: ["세븐앤아이(세븐일레븐)", "알리멘타시옹 쿠슈타르", "일본제철", "US스틸", "니덱", "마키노"],
      toon: [["🏪", "캐나다 편의점 회사가 세븐일레븐을 사겠다고?"], ["📘", "정부 지침: 진지한 제안은 이사회가 진지하게 검토하시오."]],
      b: "2023년 일본 정부가 '기업 인수 행동 지침'을 냈어요. 경영진이 싫다는 이유만으로 인수 제안을 뭉개지 말라는 내용이에요.\n2024년 캐나다 **쿠슈타르**가 **세븐앤아이**에 약 7조 엔 규모 인수를 제안했어요. 일본 기업을 향한 사상 최대 외국 제안이었어요. 1년 가까운 줄다리기 끝에 2025년 쿠슈타르가 물러났어요.\n거꾸로 **일본제철**은 미국 **US스틸**을 약 149억 달러에 사기로 했고, 미국 정치권의 반대를 넘어 2025년 마쳤어요. 정밀 모터 회사 **니덱**은 상대가 원치 않는 공개매수를 걸기도 했어요.",
      w: "'동의 없는 인수 제안', '경영진 인수(MBO)', '공개매수'가 일본발 기사에 쏟아지는 이유." } ] },
  { id: "cn", flag: "🇨🇳", name: "중국", intro: "시장을 연 지 40여 년. 외국 돈으로 큰 인터넷 기업들, 그 위에 선 나라의 손, 그리고 미국과의 갈라서기. 텐센트, 알리바바, 바이트댄스, 앤트, 디디, 헝다가 나와요.", items: [
    { y: "1978~92", t: "개혁개방과 첫 주식", wk: "Shenzhen", co: ["선전 경제특구", "상하이 페이러 음향", "선전발전은행", "훙하이(폭스콘)"],
      toon: [["🐈", "검은 고양이든 흰 고양이든 쥐만 잡으면 된다. — 덩샤오핑"], ["📄", "미국 손님에게 선물한 중국 첫 주식 한 장."]],
      b: "1978년 덩샤오핑이 시장을 열기 시작했어요. 1980년 어촌 **선전**이 경제특구가 돼 홍콩·대만 공장이 건너왔어요.\n1984년 상하이의 한 음향 회사가 중국 첫 공개 주식을 냈어요. 1986년 덩샤오핑은 뉴욕증권거래소 회장에게 그 주식 한 장을 선물했어요.\n1990년 12월 상하이와 선전에 거래소가 열렸어요. 1992년 선전에서는 주식 청약표를 사려고 100만 명이 몰려 소동이 났어요. 그해 감독 기구(증감회)가 생겼어요.",
      w: "'사회주의 나라의 주식시장'. 지금도 중국 증시는 정부 정책에 따라 크게 움직여요." },
    { y: "1997~2000", t: "달러 벤처캐피털과 VIE 구조", wk: "Sina_Corporation", co: ["시나", "소후", "넷이즈", "IDG", "골드만삭스", "나스닥"],
      toon: [["🚫", "외국인은 중국 인터넷 회사 주식을 가질 수 없소."], ["🏝️", "그럼 케이맨 제도에 회사를 세우고 '계약'으로 묶죠."]],
      b: "중국은 인터넷·미디어에 외국인 투자를 막았어요. 하지만 돈은 미국 벤처캐피털에 있었어요.\n해법이 **VIE 구조**예요. 케이맨 제도에 껍데기 회사를 세워 외국 돈을 받고, 중국 안의 진짜 회사와는 지분이 아니라 계약으로 이익을 넘겨받아요. 2000년 포털 **시나**가 이 방법으로 나스닥에 상장했고, 소후·넷이즈가 뒤따랐어요.\nIDG, 세쿼이아 차이나 같은 달러 펀드가 이 길로 중국 인터넷에 투자했어요.",
      w: "미국에 상장한 중국 회사 주식은 엄밀히는 '계약상 권리'예요. 미중 갈등 때마다 이 구조가 위험으로 거론돼요." },
    { y: "1999~2004", t: "텐센트와 알리바바, 세기의 투자 둘", wk: "Tencent", co: ["텐센트", "내스퍼스(MIH)", "알리바바", "소프트뱅크", "골드만삭스", "야후"],
      toon: [["🐧", "메신저 회사 지분 46%를 3,200만 달러에 샀어요. — 남아공 신문사"], ["🛍️", "야후가 알리바바 40%를 10억 달러에. 훗날 야후 본업보다 값졌죠."]],
      b: "1998년 선전에서 **텐센트**가 메신저 QQ로 시작했어요. 돈이 떨어져 회사를 팔려 해도 사는 곳이 없었어요. 2001년 남아공 미디어 회사 **내스퍼스**가 지분 46.5%를 3,200만 달러에 샀어요. 이 지분은 뒤에 1,000억 달러를 넘겼어요.\n1999년 항저우 아파트에서 마윈이 **알리바바**를 시작했어요. 골드만삭스와 소프트뱅크가 투자했고, 2005년 야후가 10억 달러에 지분 40%를 샀어요.\n텐센트는 2004년 홍콩에 상장했어요.",
      w: "벤처 역사에서 가장 큰 수익 두 건이 다 중국에서, 다 외국 투자자에게서 나왔어요." },
    { y: "2001~08", t: "WTO, 국유기업 상장, 그리고 4조 위안", wk: "Industrial_and_Commercial_Bank_of_China", co: ["중국공상은행(ICBC)", "페트로차이나", "중국건설은행", "CIC(중국투자공사)", "블랙스톤"],
      toon: [["🏦", "세계 최대 상장: 공상은행, 219억 달러."], ["🛣️", "금융위기? 4조 위안을 풀어 길과 아파트를 지읍시다."]],
      b: "2001년 세계무역기구에 들어간 중국은 '세계의 공장'이 됐어요. 정부는 큰 국유 은행과 석유 회사를 홍콩·상하이에 상장시켰어요. 2006년 **공상은행**은 219억 달러로 당시 세계 최대 상장을 했어요.\n2007년 쌓인 외화로 국부펀드 **CIC**를 만들었고, 첫 투자가 미국 사모펀드 블랙스톤 지분이었어요.\n2008년 금융위기에 4조 위안 부양책으로 맞섰어요. 지방정부와 부동산 회사의 빚이 이때부터 불어났어요.",
      w: "헝다 사태(2021)의 씨앗이 2008년 부양책이에요. 빚으로 지은 성장의 뒷면." },
    { y: "2010~15", t: "모바일 인터넷과 '돈 태우기' 전쟁", wk: "DiDi", co: ["디디", "콰이디", "우버 차이나", "메이퇀", "디엔핑", "샤오미", "텐센트", "알리바바"],
      toon: [["🚕", "택시 한 번 타면 보조금이 요금보다 많았어요."], ["🤝", "돈이 바닥날 때쯤, 둘이 합병했죠."]],
      b: "스마트폰이 퍼지자 텐센트와 알리바바가 편을 갈라 스타트업에 돈을 댔어요.\n차량 호출에서 텐센트 쪽 **디디**와 알리바바 쪽 **콰이디**가 승객·기사에게 보조금을 쏟아붓다 2015년 합병했어요. 이듬해 **우버 차이나**까지 흡수했어요. 음식 배달에서는 **메이퇀**과 **디엔핑**이 같은 길을 갔어요.\n'경쟁 → 출혈 → 합병 → 독점'이 중국 인터넷의 공식이 됐어요. 2014년 알리바바는 뉴욕에서 250억 달러로 세계 최대 상장을 했어요.",
      w: "쿠팡·배민의 '계획된 적자'도 같은 전략이에요. 돈으로 시장을 먼저 차지하고 나중에 번다." },
    { y: "2015", t: "증시 폭락과 '국가대표팀'", wk: "2015–2016_Chinese_stock_market_turbulence", co: ["상하이증권거래소", "중국증권금융", "중신증권(CITIC)"],
      toon: [["📈", "관영 신문이 '4,000은 강세장의 시작'이라고 썼어요."], ["🛑", "석 주 만에 30% 폭락. 상장사 절반이 거래 정지."]],
      b: "2014년 말부터 개인들이 빚을 내 주식을 사면서 상하이 지수가 1년에 2.5배가 됐어요. 관영 매체도 부추겼어요.\n2015년 6월 지수가 5,178에서 꺾여 3주 만에 30% 넘게 떨어졌어요. 정부는 신규 상장을 멈추고, 대주주의 매도를 막고, 국유 금융회사들(**'국가대표팀'**)을 시켜 주식을 사들였어요. 한때 상장사 절반이 스스로 거래를 멈췄어요.\n8월 위안화 절하까지 겹쳐 세계 증시가 흔들렸어요.",
      w: "중국 시장에서는 정부가 가장 큰 참가자예요. '국가대표팀 매수'는 지금도 기사에 나와요." },
    { y: "2015~19", t: "'대중창업'과 바이트댄스", wk: "ByteDance", co: ["바이트댄스(틱톡)", "오포(공유 자전거)", "루이싱커피", "핀둬둬", "세쿼이아 차이나", "힐하우스"],
      toon: [["🚲", "공유 자전거 회사에 20억 달러가 들어갔다 사라졌어요."], ["🎵", "그 사이 조용히 큰 회사: 틱톡의 바이트댄스."]],
      b: "2015년 정부가 '대중창업, 만중혁신'을 외치자 창업 붐이 일었어요. 공유 자전거 **오포**는 20억 달러 넘게 투자받고 무너져 자전거 무덤 사진을 남겼어요. **루이싱커피**는 창업 18개월 만에 나스닥에 갔다가 2020년 매출 조작이 드러나 퇴출됐어요.\n같은 때 **바이트댄스**는 추천 알고리즘으로 틱톡을 키워 세계에서 가장 비싼 비상장 회사가 됐고, **핀둬둬**는 창업 3년 만에 상장했어요.\n2019년 상하이에 적자 기술 기업도 상장할 수 있는 **커촹반**이 열렸어요.",
      w: "같은 붐에서 오포와 바이트댄스가 함께 나왔어요. 거품과 진짜는 같은 때 자라요." },
    { y: "2020", t: "앤트그룹, 이틀 전에 멈춘 세계 최대 상장", wk: "Ant_Group", co: ["앤트그룹", "알리바바", "알리페이", "상하이·홍콩 거래소"],
      toon: [["🎤", "중국 은행은 전당포 사고방식을 못 버렸어요. — 마윈 연설"], ["⏸️", "열흘 뒤, 340억 달러 상장이 멈췄어요."]],
      b: "알리페이를 가진 **앤트그룹**은 2020년 11월 상하이와 홍콩에 동시에 상장해 약 340억 달러를 모을 계획이었어요. 세계 최대 기록이었고 청약 돈만 3조 달러가 몰렸어요.\n10월 24일 마윈이 금융 당국을 공개 비판했어요. 11월 3일, 상장 이틀 전에 당국이 상장을 멈췄어요.\n이듬해 알리바바는 독점 행위로 약 28억 달러 벌금을 받았고, 앤트는 은행처럼 규제받는 회사로 다시 짜였어요.",
      w: "2년간 이어진 빅테크 단속의 시작. 중국 기술주 시가총액 1조 달러 이상이 사라졌어요." },
    { y: "2021", t: "디디, 사교육, 헝다: 규제의 해", wk: "Evergrande_Group", co: ["디디", "신둥팡", "TAL", "헝다(에버그란데)", "비구이위안", "텐센트"],
      toon: [["📵", "뉴욕 상장 이틀 뒤, 앱이 스토어에서 내려갔어요."], ["🏗️", "빚 3,000억 달러의 부동산 회사가 이자를 못 냈어요."]],
      b: "6월 30일 **디디**가 뉴욕에 상장해 44억 달러를 모았어요. 이틀 뒤 당국이 데이터 보안 조사를 시작하고 앱을 내리게 했어요. 디디는 1년 뒤 뉴욕에서 상장폐지했어요.\n7월에는 사교육 회사가 이익을 내지 못하게 하는 규제가 나와 **신둥팡**, **TAL** 주가가 하루에 반 토막 났어요.\n가을에는 빚 3,000억 달러의 부동산 회사 **헝다**가 이자를 못 냈어요. 중국 경제의 4분의 1쯤을 차지하던 부동산이 긴 침체에 들어갔어요.",
      w: "외국 투자자들이 '중국은 투자할 수 있는 곳인가'를 묻게 된 해. 달러 펀드의 중국 투자가 이후 크게 줄었어요." },
    { y: "2018~24", t: "기술 자립과 나라의 돈", wk: "Semiconductor_Manufacturing_International_Corporation", co: ["화웨이", "SMIC", "국가 반도체 펀드(빅펀드)", "BYD", "CATL", "허페이시 정부", "니오"],
      toon: [["🚫", "미국: 화웨이에 칩을 팔지 마시오."], ["🏛️", "그럼 나라가 펀드를 만들어 직접 키우겠소."]],
      b: "2019년 미국이 **화웨이**를 거래 제한 명단에 올리고, 2022년 첨단 반도체 장비 수출을 막았어요.\n중국은 나라 돈으로 맞섰어요. **국가 반도체 펀드**(1~3기 합쳐 약 1,000억 달러)가 **SMIC** 등에 투자했어요. 지방정부도 벤처캐피털처럼 움직였어요. 허페이시는 망해 가던 전기차 **니오**에 투자해 큰 이익을 냈어요.\n전기차 **BYD**와 배터리 **CATL**은 세계 1위가 됐어요. 2023년 미국은 반도체·양자·AI 분야 중국 투자를 제한하는 행정명령을 냈어요.",
      w: "중국 딜 기사에 '국유 자본', '○○시 산업기금', '정부 인도 기금'이 나오는 이유. 가장 큰 벤처 투자자가 정부예요." },
    { y: "2023~25", t: "홍콩으로 돌아온 상장, 그리고 딥시크", wk: "Hong_Kong_Stock_Exchange", co: ["홍콩거래소", "CATL", "쉬인", "딥시크", "알리바바", "텐센트", "유니트리"],
      toon: [["🇭🇰", "뉴욕은 어렵고 상하이는 좁으니 홍콩으로."], ["🐳", "작은 회사가 내놓은 AI에 엔비디아 주가가 하루 17% 빠졌어요."]],
      b: "미국 상장이 어려워지자 중국 회사들은 홍콩으로 갔어요. 2025년 배터리 회사 **CATL**이 홍콩에 상장해 그해 세계 최대급 상장을 했어요. 패션 앱 **쉬인**은 뉴욕과 런던 상장이 잇따라 막혔어요.\n2025년 1월 항저우의 **딥시크**가 싼 비용으로 만든 AI 모델을 공개하자 엔비디아 주가가 하루에 17% 떨어졌어요. '중국 기술주를 다시 봐야 한다'는 말이 나왔고, 알리바바·텐센트 주가가 크게 올랐어요.",
      w: "'규제로 죽었다'던 중국 기술주가 AI로 다시 주목받고 있어요. 다만 돈은 여전히 나라 안에서 주로 돌아요." } ] },
  { id: "kr", flag: "🇰🇷", name: "한국", intro: "은행 대출과 재벌로 큰 나라가 외환위기를 겪고, 벤처와 사모펀드라는 새 돈줄을 갖게 되기까지. 삼성·현대·대우, 새롬·네이버, 론스타·MBK, 카카오·쿠팡·배민이 나와요.", items: [
    { y: "1956~72", t: "거래소, 그리고 사채를 얼린 8·3 조치", wk: "Korea_Exchange", co: ["대한증권거래소", "조흥은행", "경성방직", "삼성", "현대"],
      toon: [["📜", "상장사 12곳으로 시작. 거래의 대부분은 나라 채권이었어요."], ["🧊", "기업이 빌린 사채, 오늘부터 3년 동안 안 갚아도 됩니다."]],
      b: "1956년 서울에 **대한증권거래소**가 열렸어요. 상장사는 은행·방직 회사 등 12곳뿐이었어요.\n기업들은 주식보다 빚으로 컸어요. 은행 돈이 모자라 높은 이자의 사채를 썼고, 1972년 줄도산 위기가 오자 정부는 **8·3 조치**로 사채 상환을 얼리고 이자를 강제로 낮췄어요. 돈 빌려준 사람들의 재산권을 누르고 기업을 살린 거예요.\n대신 정부는 기업들에 '주식시장에 상장하라'고 밀어붙였어요(1972 기업공개촉진법).",
      w: "'기업은 빚으로 크고, 위기 때는 나라가 구한다'는 한국식 성장의 원형. 대마불사(큰 회사는 안 망한다) 믿음이 여기서 나와요." },
    { y: "1973~89", t: "중화학과 재벌, 국민주", wk: "Chaebol", co: ["현대중공업", "포항제철(포스코)", "삼성전자", "대우", "한국전력"],
      toon: [["🚢", "조선소도 없이 배 주문부터 받았죠. 500원 지폐의 거북선을 보여 주며."], ["🧾", "1988년, 포항제철 주식을 국민 수백만 명에게."]],
      b: "1973년 정부는 철강·조선·화학·전자를 키우기로 하고 은행 돈을 몇몇 기업에 몰아줬어요. **현대**는 조선과 자동차, **삼성**은 전자, **대우**는 인수로 덩치를 키웠어요. 총수 가족이 적은 지분으로 계열사끼리 서로 출자해 그룹 전체를 쥐는 구조가 굳었어요.\n1980년대 후반 3저 호황(낮은 금리·유가·달러)에 주가가 폭등했어요. 정부는 1988년 **포항제철**, 1989년 **한국전력** 주식을 국민주로 팔았어요. 1989년 종합주가지수가 처음 1,000을 넘었어요.",
      w: "'총수 지분은 작은데 그룹을 지배한다'. 지금 지배구조·승계 기사(지주회사, 순환출자)의 뿌리예요." },
    { y: "1986~96", t: "창업투자회사와 코스닥", wk: "KOSDAQ", co: ["한국기술개발(KTB)", "한국종합기술금융", "메디슨", "휴맥스", "터보테크", "코스닥"],
      toon: [["🔬", "대학 연구실에서 나온 벤처 1세대: 메디슨, 휴맥스."], ["📊", "1996년 7월, 이들을 위한 시장이 열렸어요."]],
      b: "1986년 창업투자회사 제도가 생겼어요. 한국기술개발(뒤의 KTB) 같은 곳이 기술 회사에 지분 투자를 시작했어요.\n카이스트 출신들이 세운 초음파 진단기 회사 **메디슨**(1985), 셋톱박스의 **휴맥스**(1989)가 벤처 1세대예요.\n1996년 7월 **코스닥**이 열리고, 1997년 벤처기업 특별법이 만들어졌어요. 코스피에 못 가던 기술 회사가 상장할 길이 생겼어요.",
      w: "'○○인베스트먼트', '○○창투'가 이 제도의 후손이에요. 코스닥은 나스닥을 본떴어요." },
    { y: "1997~99", t: "외환위기: 30대 재벌의 절반이 사라지다", wk: "1997_Asian_financial_crisis", co: ["한보철강", "기아자동차", "대우그룹", "제일은행", "뉴브리지캐피털", "현대자동차", "IMF"],
      toon: [["💣", "한보, 삼미, 진로, 기아… 1997년 한 해에 줄줄이."], ["🏦", "제일은행을 미국 사모펀드에 5,000억 원에 팔았어요."]],
      b: "1997년 1월 **한보철강** 부도를 시작으로 재벌이 줄줄이 무너졌어요. 빚이 자본의 몇 배였어요. 외국 은행들이 돈을 거둬 가자 외화가 바닥났고 12월 IMF 구제금융을 받았어요.\n**기아**는 현대자동차에 팔렸고(1998), 1999년 재계 2위 **대우**가 해체됐어요. 사상 최대 부도였어요. 30대 재벌의 절반이 사라졌어요.\n1999년 **제일은행**이 미국 사모펀드 **뉴브리지캐피털**에 팔렸어요. 한국 은행이 외국 사모펀드에 넘어간 첫 사례예요. 뉴브리지는 2005년 스탠다드차타드에 되팔아 1조 원 넘게 벌었어요.",
      w: "한국에 인수합병, 구조조정, 사모펀드, 외국인 주주가 한꺼번에 들어온 계기. 지금 시장의 규칙이 이때 다시 쓰였어요." },
    { y: "1999~2000", t: "벤처 붐: 새롬, 다음, 그리고 거품", wk: "Naver", co: ["새롬기술", "다음커뮤니케이션", "네이버컴", "한게임", "엔씨소프트", "골드뱅크", "KTB"],
      toon: [["📞", "공짜 인터넷 전화! 새롬기술 주가 반년 만에 100배 넘게."], ["🧩", "그해 네이버와 한게임이 합쳤어요. 조용히."]],
      b: "정부의 벤처 육성과 초고속 인터넷이 만났어요. 무료 인터넷 전화 '다이얼패드'의 **새롬기술**은 1999년 8월부터 반년 만에 주가가 100배 넘게 올라 시가총액이 한때 대기업을 넘었어요. 광고를 보면 돈을 준다던 **골드뱅크**도 있었어요.\n2000년 3월 코스닥이 꺾여 연말까지 약 80% 떨어졌어요. 새롬은 사라졌어요.\n하지만 그해 **네이버컴**이 **한게임**과 합병했고(지금의 네이버), **엔씨소프트**가 상장했어요. 다음, 옥션도 이 시기에 자랐어요.",
      w: "거품이 꺼져도 회사는 남는다의 한국판. 지금 한국 인터넷 대기업은 거의 다 이때 태어났어요." },
    { y: "2003~12", t: "론스타와 외환은행, 그리고 토종 사모펀드", wk: "Korea_Exchange_Bank", co: ["론스타", "외환은행", "하나금융", "칼라일", "한미은행", "MBK파트너스", "한앤컴퍼니", "IMM"],
      toon: [["🦅", "1조 4천억에 사서 3조 9천억에 팔고 떠났어요. '먹튀'!"], ["🇰🇷", "우리도 사모펀드를 만들자. — 2004년 법 개정"]],
      b: "2003년 미국 사모펀드 **론스타**가 **외환은행**을 약 1.4조 원에 샀어요. 헐값 매각 논란과 주가 조작 재판이 이어졌고, 2012년 하나금융에 약 3.9조 원에 팔고 떠났어요. 배당까지 합쳐 4조 원 넘게 벌었어요. 한국 정부와의 국제 중재는 2022년까지 갔어요.\n'외국 펀드만 돈을 번다'는 반성에서 2004년 국내 사모펀드 제도가 생겼어요. 칼라일에서 한미은행 인수를 이끈 김병주가 2005년 **MBK파트너스**를 세웠고, IMM, 한앤컴퍼니가 뒤를 이었어요.",
      w: "한국에서 사모펀드를 보는 불편한 눈길의 뿌리이자, 지금 인수전의 주역(MBK·한앤코·IMM)이 태어난 때예요." },
    { y: "2005~10", t: "모태펀드와 스마트폰 세대", wk: "Pangyo_Techno_Valley", co: ["한국벤처투자(모태펀드)", "카카오", "쿠팡", "우아한형제들", "티몬", "본엔젤스", "소프트뱅크벤처스"],
      toon: [["🫖", "정부가 직접 고르지 않고, 민간 펀드에 종잣돈을 댑니다."], ["💬", "2010년: 카카오톡, 쿠팡, 배달의민족이 한 해에."]],
      b: "닷컴 붕괴로 벤처 투자가 말라붙자 2005년 정부가 **모태펀드**를 만들었어요. 정부가 회사를 직접 고르지 않고 민간 벤처펀드에 돈을 대는 방식이에요. 이스라엘 요즈마를 참고했어요.\n2009년 아이폰이 들어오자 판이 바뀌었어요. 2010년 한 해에 **카카오톡**, **쿠팡**, **배달의민족**, 티몬이 나왔어요.\n네이버·넥슨·엔씨 출신들이 창업하고, 먼저 성공한 창업자들이 엔젤 투자자(본엔젤스 등)가 됐어요.",
      w: "모태펀드는 지금도 한국 벤처펀드의 가장 큰 출자자예요. '모태펀드 예산'이 곧 벤처 투자 날씨예요." },
    { y: "2014~16", t: "카카오의 합병과 인수", wk: "Kakao", co: ["카카오", "다음", "로엔엔터테인먼트(멜론)", "어피너티", "김기사(록앤올)"],
      toon: [["🔀", "비상장 카카오가 상장사 다음과 합쳐 한 번에 상장."], ["🎶", "멜론을 1조 8,700억 원에. 판 쪽은 홍콩계 사모펀드."]],
      b: "2014년 **카카오**가 포털 **다음**과 합병했어요. 비상장 회사가 상장사와 합쳐 상장하는 '우회 상장'이었고, 합병 뒤 주도권은 카카오가 쥐었어요.\n2015년 내비게이션 '김기사'를 626억 원에 샀고, 2016년 음원 서비스 멜론의 **로엔**을 1조 8,700억 원에 샀어요. 판 쪽은 2013년에 로엔을 샀던 사모펀드 **어피너티**로, 3년 만에 큰 이익을 냈어요.\n카카오는 이후 계열사를 100개 넘게 늘리고 자회사를 따로 상장시켰어요.",
      w: "사모펀드가 사서 키워 대기업에 파는 회수의 본보기. 카카오의 '쪼개기 상장'은 뒤에 큰 논란이 돼요." },
    { y: "2015~19", t: "소프트뱅크의 쿠팡, 그리고 배민 매각", wk: "Coupang", co: ["쿠팡", "소프트뱅크 비전펀드", "세쿼이아", "블랙록", "우아한형제들", "딜리버리히어로", "요기요", "힐하우스"],
      toon: [["🚚", "적자가 조 단위인데 또 20억 달러를 넣는다고?"], ["🍜", "배민은 경쟁사 요기요의 주인에게 팔렸어요. 4조 7,500억."]],
      b: "**쿠팡**은 2015년 소프트뱅크에게서 10억 달러, 2018년 비전펀드에게서 20억 달러를 받았어요. 해마다 수천억~조 단위 적자를 내며 물류센터를 지었어요. '계획된 적자'라고 했어요.\n2019년 12월 독일 **딜리버리히어로**가 **배달의민족**을 40억 달러(약 4.75조 원) 가치로 사기로 했어요. 딜리버리히어로는 2위 요기요의 주인이었어요. 공정위는 1년 뒤 '요기요를 팔아라'는 조건으로 승인했어요.\n한국 스타트업 사상 최대 매각이었어요.",
      w: "'기업결합 심사'가 거래 모양을 바꾼 대표 사례. 창업자와 초기 투자자(본엔젤스 등)가 큰 회수를 했어요." },
    { y: "2020~21", t: "공모주 열풍과 제2 벤처 붐", wk: "Krafton", co: ["SK바이오팜", "카카오게임즈", "빅히트(하이브)", "쿠팡", "크래프톤", "카카오뱅크", "하이퍼커넥트", "매치그룹", "두나무", "야놀자"],
      toon: [["🙋", "공모주 청약에 58조 원이 몰렸어요. 1주 받으려고."], ["🗽", "쿠팡은 뉴욕으로 갔죠. 첫날 시가총액 100조 원."]],
      b: "2020년 '동학개미'가 주식시장에 들어왔어요. **SK바이오팜**, **카카오게임즈**(청약 증거금 58조 원), 빅히트 공모주에 돈이 몰렸어요.\n2021년 3월 **쿠팡**이 뉴욕증권거래소에 상장해 약 46억 달러를 모았어요. 첫날 시가총액이 약 100조 원이었어요. 영상 채팅 **하이퍼커넥트**는 미국 매치그룹에 약 1.9조 원에 팔렸어요. **크래프톤**, **카카오뱅크**가 상장했어요.\n그해 벤처 투자는 7조 원대로 사상 최대, 유니콘이 18곳으로 늘었어요.",
      w: "이때 높은 값에 투자받은 회사들이 2023~25년 '값을 깎은 투자', '상장 연기', '매각' 기사로 돌아와요." },
    { y: "2022", t: "LG에너지솔루션과 물적분할 논란, 그리고 혹한기", wk: "LG_Energy_Solution", co: ["LG화학", "LG에너지솔루션", "카카오페이", "레고랜드(강원중도개발공사)", "메쉬코리아", "왓챠"],
      toon: [["🔋", "배터리 보고 LG화학 샀는데, 배터리만 떼어 따로 상장한다고요?"], ["🧱", "레고랜드 빚 보증 한 건에 채권시장이 얼어붙었어요."]],
      b: "1월 **LG에너지솔루션**이 공모 12.75조 원으로 한국 사상 최대 상장을 했어요. LG화학이 알짜 사업을 100% 자회사로 떼어(물적분할) 상장한 것이라 기존 주주들이 반발했어요. 이후 분할 때 주주를 보호하는 규칙이 생겼어요.\n금리가 오르자 하반기부터 벤처 투자가 급히 식었어요. 9월 강원도가 **레고랜드** 개발 빚 보증을 안 서겠다고 하자 채권시장이 얼어붙어 기업들이 돈을 못 구했어요.\n배달 대행 **메쉬코리아**, OTT **왓챠** 같은 회사가 매각으로 내몰렸어요.",
      w: "'쪼개기 상장', '투자 혹한기', '다운 라운드'가 일상어가 된 해. 지방정부 보증 한 건이 시장 전체를 흔들 수 있다는 것도요." },
    { y: "2023~25", t: "경영권 분쟁의 시대", wk: "Korea_Zinc", co: ["SM엔터테인먼트", "하이브", "카카오", "고려아연", "영풍", "MBK파트너스", "홈플러스", "오스템임플란트", "한앤컴퍼니", "남양유업"],
      toon: [["🎤", "SM을 두고 하이브와 카카오가 공개매수로 맞붙었어요."], ["⚒️", "75년 동업한 두 집안이 갈라서고, 사모펀드가 한쪽 편에 섰죠."]],
      b: "2023년 **SM엔터테인먼트**를 두고 하이브와 **카카오**가 공개매수 경쟁을 벌여 카카오가 이겼어요. 그 과정의 주가 조작 혐의로 카카오 경영진이 재판을 받았어요.\n2024년 **고려아연**을 두고 최대 주주 영풍과 **MBK파트너스**가 공개매수에 나서고 경영진이 맞서는, 한국 사상 최대급 경영권 분쟁이 벌어졌어요.\n2025년에는 MBK가 2015년 7.2조 원에 산 **홈플러스**가 법정관리에 들어가 사모펀드의 책임 논란이 커졌어요. 그해 이사가 주주 전체의 이익을 지키도록 하는 상법 개정이 이뤄졌어요.",
      w: "공개매수, 행동주의, 사모펀드, 주주 권리. 요즘 한국 딜 기사의 낱말이 다 이 몇 해에 나왔어요." } ] },

  { id: "in", flag: "🇮🇳", name: "인도", intro: "아시아에서 가장 오래된 거래소, 40년의 허가제, 1991년의 개방, 그리고 14억 명의 스마트폰. 타타·릴라이언스·인포시스·플립카트가 주인공이에요.", items: [
    { y: "1875", t: "반얀나무 아래에서 시작한 봄베이 거래소", wk: "Bombay_Stock_Exchange", co: ["봄베이 증권거래소(BSE)", "타타 그룹"],
      toon: [["🌳", "면화 값이 뛰니 주식 중개인들이 나무 아래 모였지."], ["🏛️", "그게 아시아에서 가장 오래된 거래소가 됐어요."]],
      b: "미국 남북전쟁으로 면화 값이 뛰자 봄베이(지금의 뭄바이)에 돈이 몰렸어요. 반얀나무 아래에서 주식을 사고팔던 중개인들이 1875년 협회를 만들었어요. **봄베이 증권거래소(BSE)**, 아시아에서 가장 오래된 거래소예요.\n비슷한 때 잠셋지 타타가 무역 회사(1868)를 세웠어요. 아들 대에 **타타스틸**(1907)을 지을 때는 인도 사람 수천 명이 주식을 사서 돈을 댔어요. 영국 자본 없이 지은 첫 큰 공장이었어요.",
      w: "타타는 지금도 인도에서 가장 큰 그룹이에요. 인도 인수합병 기사에 가장 자주 나오는 이름." },
    { y: "1947~90", t: "허가제의 나라 (라이선스 라지)", wk: "Licence_Raj", co: ["인도 정부", "타타", "비를라", "에어인디아"],
      toon: [["📋", "공장을 늘리려고요? 허가 80개 받아 오세요."], ["😮‍💨", "스쿠터 한 대 사려고 10년을 기다렸어."]],
      b: "독립한 인도는 나라가 계획하는 경제를 택했어요. 무엇을 얼마나 만들지 정부 허가가 필요했어요. 이것을 '라이선스 라지(허가의 통치)'라고 불러요.\n은행과 보험, 타타가 세운 **에어인디아**까지 나라 것이 됐어요. 외국 회사 지분은 40%로 묶여, 1977년 코카콜라와 IBM이 인도를 떠났어요.\n경쟁이 없으니 물건은 모자라고 성장은 느렸어요.",
      w: "'인도는 규제가 많다'는 말의 뿌리. 2022년 타타가 에어인디아를 되사 온 것은 이 시대가 끝났다는 상징이었어요." },
    { y: "1977", t: "릴라이언스, 보통 사람들의 주식", wk: "Reliance_Industries", co: ["릴라이언스 인더스트리", "봄베이 증권거래소"],
      toon: [["🧵", "은행이 안 빌려주면, 국민에게서 직접 모으지."], ["🏟️", "주주가 너무 많아 주주총회를 축구장에서 열었대요."]],
      b: "주유소 직원 출신 디루바이 암바니는 섬유 회사 **릴라이언스**를 키우면서 은행 대신 보통 사람들에게 주식을 팔았어요. 1977년 상장 때 약 5만 8천 명이 주식을 샀어요.\n주가가 오르자 소도시의 가게 주인, 교사들이 주식에 눈을 떴어요. 주주총회를 경기장에서 열 만큼 주주가 많았어요.\n릴라이언스는 섬유에서 석유화학, 정유, 통신으로 넓혀 인도에서 가장 큰 회사가 됐어요.",
      w: "인도에 '주식 문화'를 만든 회사. 지금은 아들 무케시 암바니가 이끌며 통신(지오)·유통으로 딜 기사에 늘 나와요." },
    { y: "1991", t: "금을 저당 잡히고 문을 열다", wk: "Economic_liberalisation_in_India", co: ["인도 중앙은행(RBI)", "IMF", "인도 증권거래위원회(SEBI)", "인도 국립증권거래소(NSE)"],
      toon: [["✈️", "외화가 2주 치 수입대금밖에 없어요. 금을 비행기에 실어 보냅시다."], ["🔓", "어떤 힘도 때가 된 생각을 막을 수 없습니다. — 만모한 싱 재무장관"]],
      b: "1991년 인도는 외화가 바닥나 2~3주 치 수입대금밖에 남지 않았어요. 정부는 **금을 비행기에 실어** 영국·스위스에 저당 잡히고 돈을 빌렸어요.\nIMF 지원을 받으며 재무장관 만모한 싱이 허가제를 걷어 내고, 관세를 내리고, 외국인 투자를 열었어요.\n이듬해 증권 중개인 하르샤드 메타의 대형 주가 조작이 터지자, 감독 기구 **SEBI**에 힘을 싣고 전자 거래소 **NSE**를 세웠어요(1994년 거래 시작).",
      w: "한국의 1997년과 닮았어요. 위기가 개방을 불렀고, 지금의 인도 시장은 이때 만들어졌어요." },
    { y: "1993~2004", t: "IT 서비스: 세계의 뒷사무실", wk: "Infosys", co: ["인포시스", "TCS(타타 컨설턴시)", "위프로", "나스닥"],
      toon: [["💻", "미국 회사 프로그램을 인도에서 밤새 고쳐 드립니다."], ["🚗", "창업자 운전기사까지 스톡옵션으로 부자가 됐대."]],
      b: "방갈로르의 **인포시스**는 1981년 일곱 명이 250달러로 시작한 회사예요. 1993년 상장하고, 1999년 인도 회사로는 처음 나스닥에 올랐어요.\n2000년 문제(Y2K)를 고치려는 미국·유럽 회사들의 일감이 인도로 쏟아졌어요. 인포시스는 직원들에게 스톡옵션을 넓게 나눠 줘 평범한 직원 수천 명이 부자가 됐어요.\n2004년 타타의 **TCS**가 상장했어요. 지금도 인도에서 시가총액이 가장 큰 회사 가운데 하나예요.",
      w: "이때 쌓인 기술 인력과 '직원도 주식으로 부자가 된다'는 경험이 다음 세대 스타트업의 밑천이 됐어요." },
    { y: "2007~08", t: "타타, 옛 주인의 회사를 사다", wk: "Jaguar_Land_Rover", co: ["타타스틸", "코러스", "타타모터스", "재규어 랜드로버", "보다폰", "허치슨 에사르"],
      toon: [["🇬🇧", "식민지 회사가 영국 철강과 재규어를 산다고?"], ["🚙", "네. 현금으로요."]],
      b: "2007년 **타타스틸**이 영국·네덜란드 철강사 코러스를 약 120억 달러에 샀어요. 자기보다 몇 배 큰 회사였어요. 2008년에는 **타타모터스**가 포드에게서 재규어 랜드로버를 23억 달러에 샀어요.\n같은 2007년 영국 **보다폰**은 인도 통신사 허치슨 에사르를 약 110억 달러에 샀어요. 인도 정부는 뒤늦게 세금 수십억 달러를 매겼고, 법을 과거까지 소급해 고치며 10년 넘게 싸웠어요.",
      w: "두 가지 교훈. 신흥국 기업도 선진국 회사를 산다. 그리고 인도 투자에는 '세금·규제 위험'이 따라다닌다." },
    { y: "2016", t: "지오와 UPI: 14억 명이 온라인으로", wk: "Jio", co: ["릴라이언스 지오", "인도결제공사(NPCI)", "페이티엠", "폰페"],
      toon: [["📶", "데이터를 거의 공짜로 드립니다. 통화는 평생 무료."], ["📲", "노점에서도 QR로 받아요. 수수료는 0."]],
      b: "2016년 9월 릴라이언스가 통신사 **지오**를 열고 데이터를 사실상 공짜로 뿌렸어요. 몇 해 만에 수억 명이 스마트폰으로 인터넷에 들어왔고, 인도의 데이터 값은 세계에서 가장 싼 축이 됐어요.\n같은 해 정부 주도로 만든 실시간 송금망 **UPI**가 나왔고, 11월에는 고액권을 하루아침에 없앤 화폐 개혁이 있었어요. 현금이 모자라자 사람들이 **페이티엠** 같은 결제 앱으로 몰렸어요.",
      w: "인도 스타트업 붐의 바닥 공사. '인터넷 쓰는 사람 수억 명'이 생기자 해외 돈이 들어오기 시작했어요." },
    { y: "2018", t: "월마트, 플립카트를 160억 달러에", wk: "Flipkart", co: ["플립카트", "월마트", "아마존", "소프트뱅크", "타이거글로벌", "내스퍼스"],
      toon: [["📦", "아마존 직원 둘이 나와서 책을 팔기 시작했어요."], ["🛒", "11년 뒤, 월마트가 160억 달러를 냈죠."]],
      b: "아마존 인도 사무소에서 일하던 두 사람이 2007년 방갈로르 아파트에서 온라인 서점 **플립카트**를 열었어요. 카드가 없는 인도에 맞춰 '물건 받고 현금 내기'를 퍼뜨렸어요.\n2018년 미국 **월마트**가 지분 77%를 약 160억 달러에 샀어요. 그때까지 세계 최대 전자상거래 인수였어요. 소프트뱅크는 1년도 안 돼 투자금을 크게 불려 나갔어요.\n이 한 건으로 초기 직원 수백 명이 부자가 됐고, 그들이 다음 창업자와 엔젤 투자자가 됐어요.",
      w: "인도판 '페어차일드'. 플립카트 출신이 만든 회사만 수백 개예요(폰페, 큐어핏 등)." },
    { y: "2020~22", t: "돈의 홍수와 상장 붐", wk: "Paytm", co: ["지오 플랫폼", "메타(페이스북)", "구글", "조마토", "페이티엠", "LIC", "바이주스"],
      toon: [["💸", "코로나 한복판에 지오가 200억 달러를 모았어요."], ["📉", "인도 최대 상장이라던 페이티엠, 첫날 27% 빠졌어요."]],
      b: "2020년 봄 **지오 플랫폼**이 석 달 만에 200억 달러 넘게 투자받았어요. 페이스북이 57억 달러, 구글이 45억 달러를 넣었어요.\n2021년 인도에서 유니콘이 40곳 넘게 새로 나왔어요. 음식 배달 **조마토**가 상장에 성공했고, 결제 회사 **페이티엠**은 당시 인도 최대 규모로 상장했다가 첫날 27% 떨어졌어요.\n2022년에는 국영 생명보험 **LIC**가 새 최대 상장 기록을 썼어요. 한때 220억 달러 가치였던 교육 회사 **바이주스**는 회계와 빚 문제로 무너졌어요.",
      w: "값을 너무 높게 매긴 상장과 투자가 어떻게 끝나는지, 인도도 같은 수업료를 냈어요." },
    { y: "2023~24", t: "아다니 충격, 그리고 세계에서 가장 바쁜 상장 시장", wk: "Adani_Group", co: ["아다니 그룹", "힌덴버그 리서치", "현대자동차 인도법인", "타타"],
      toon: [["📑", "공매도 회사 보고서 한 편에 시가총액 1,000억 달러가 날아갔어요."], ["🚗", "한국 현대차가 인도에서 인도 사상 최대 상장을 했죠."]],
      b: "2023년 1월 미국 공매도 회사 **힌덴버그**가 항만·에너지 재벌 **아다니 그룹**의 주가 조작과 회계 의혹을 제기했어요. 며칠 만에 그룹 시가총액이 1,000억 달러 넘게 줄었어요. 아다니는 부인했고 주가는 뒤에 많이 회복했어요.\n그래도 인도 증시는 계속 올랐어요. 적금처럼 다달이 펀드에 넣는 개인 돈이 받쳐 줬어요. 2024년 인도는 상장 건수에서 세계 선두였고, 10월 **현대자동차 인도법인**이 약 33억 달러로 인도 사상 최대 상장을 했어요.",
      w: "중국에서 빠진 세계 돈이 인도를 보는 이유. 한국 기업에도 '인도 자회사 상장'이 선택지가 됐어요." } ] },

  { id: "tr", flag: "🇹🇷", name: "튀르키예", intro: "제국의 빚, 재벌(홀딩)의 나라, 되풀이되는 통화 위기. 그 사이에서 게임·배달·쇼핑 스타트업이 세계에 팔렸어요.", items: [
    { y: "1875~81", t: "오스만 제국의 부도와 빚 관리국", wk: "Ottoman_Public_Debt_Administration", co: ["오스만 은행", "오스만 채무관리국"],
      toon: [["🕌", "전쟁과 철도 때문에 빌린 돈, 이자도 못 내겠소."], ["🧾", "그럼 소금·담배 세금은 우리가 직접 걷겠습니다. — 유럽 채권자들"]],
      b: "오스만 제국은 크림 전쟁 뒤 유럽에서 돈을 빌리기 시작했다가 1875년 이자를 못 내게 됐어요.\n1881년 유럽 채권자들이 **채무관리국**을 세워 소금·담배·비단 세금을 직접 걷어 갔어요. 직원이 제국 재무부보다 많았다고 해요.\n나라 살림의 열쇠를 외국에 넘긴 이 경험은 깊은 상처로 남았어요.",
      w: "튀르키예가 IMF와 외국 자본에 유독 예민한 까닭. 지금도 정치인들이 이 역사를 꺼내요." },
    { y: "1923~50", t: "공화국과 나라가 세운 은행·공장", wk: "Türkiye_İş_Bankası", co: ["이쉬은행", "쉬메르방크", "코치 그룹", "사반즈 그룹"],
      toon: [["🏗️", "민간에 돈이 없으니 나라가 공장을 짓자."], ["🛒", "앙카라 구멍가게에서 시작한 코치, 훗날 나라에서 가장 큰 그룹이 돼요."]],
      b: "1923년 공화국을 세운 아타튀르크는 이듬해 민간 은행 **이쉬은행**을 세우게 했고, 1930년대에는 나라가 직접 섬유·제철 공장을 지었어요.\n이 틈에서 상인들이 자랐어요. 앙카라의 구멍가게에서 시작한 베흐비 코치의 **코치 그룹**(1926), 목화 일꾼 출신 하즈 외메르 사반즈의 **사반즈 그룹**이 대표예요.\n두 가문은 은행, 자동차, 가전, 유통을 거느린 '홀딩(지주회사)'이 됐어요.",
      w: "튀르키예 딜 기사에 '코치 홀딩', '사반즈 홀딩'이 나오면 한국의 재벌과 비슷한 것으로 보면 돼요." },
    { y: "1980~86", t: "1월 24일 결정과 이스탄불 거래소", wk: "Borsa_Istanbul", co: ["이스탄불 증권거래소(지금의 보르사 이스탄불)", "튀르키예 중앙은행"],
      toon: [["🚪", "수입 막고 우리끼리 만들던 시대는 끝. 수출로 갑니다."], ["📈", "1986년, 이스탄불에 주식시장이 다시 열렸어요."]],
      b: "1970년대 말 튀르키예는 외화가 떨어져 석유도 못 살 지경이었어요. 1980년 1월 24일 정부는 환율을 풀고 수출 중심으로 방향을 틀었어요. 설계자는 뒤에 총리가 된 투르구트 외잘.\n1986년 **이스탄불 증권거래소**가 문을 열었고, 1989년에는 외국 돈이 자유롭게 드나들게 했어요.\n수출은 늘었지만 해마다 수십 %씩 물가가 오르는 병은 고치지 못했어요.",
      w: "개방은 했는데 물가를 못 잡은 것이 이후 40년 되풀이되는 위기의 씨앗이에요." },
    { y: "2001", t: "은행 위기와 리라에서 0 여섯 개 떼기", wk: "2001_Turkish_economic_crisis", co: ["IMF", "튀르키예 예금보험기금(TMSF)", "가란티 은행", "악방크"],
      toon: [["💥", "하룻밤 금리가 수천 %까지 뛰었어요."], ["✂️", "100만 리라가 새 1리라. 0을 여섯 개 뗍니다."]],
      b: "2001년 2월 정치 다툼을 계기로 돈이 빠져나가며 리라 값이 절반이 됐어요. 은행 스무 곳 넘게 나라가 떠안았어요.\n세계은행 출신 케말 데르비쉬가 IMF 프로그램으로 은행을 정리하고 중앙은행을 독립시켰어요. 2005년에는 **0을 여섯 개 뗀 새 리라**를 냈어요.\n깨끗해진 은행은 외국 자본의 표적이 됐어요.",
      w: "'위기 → 정리 → 외국 자본의 인수'. 한국의 1997~2003년과 같은 순서예요." },
    { y: "2005~12", t: "외국 자본의 은행·통신 쇼핑", wk: "Türk_Telekom", co: ["튀르크텔레콤", "오게르 텔레콤", "가란티 은행", "GE", "BBVA", "피난스방크", "그리스 국립은행", "데니즈방크", "덱시아", "스베르방크"],
      toon: [["🏦", "깨끗해진 튀르키예 은행, 줄 서서 삽니다."], ["📞", "국영 통신사 지분 55%, 65억 달러에 낙찰!"]],
      b: "EU 가입 협상이 시작된 2005년부터 외국 돈이 밀려왔어요.\n국영 **튀르크텔레콤** 지분 55%가 사우디·레바논계 오게르에 65.5억 달러에 팔렸어요. 미국 GE가 **가란티 은행** 지분을 샀다가 뒤에 스페인 BBVA에 넘겼고, 그리스 국립은행이 **피난스방크**를, 벨기에 덱시아가 **데니즈방크**를 샀어요.\n뒤에 주인이 또 바뀌었어요. 데니즈방크는 러시아 스베르방크(2012)를 거쳐 두바이 에미리트NBD(2019)로, 피난스방크는 카타르 QNB(2016)로 갔어요.",
      w: "은행 주인의 국적이 유럽 → 러시아 → 걸프로 바뀐 흐름이 곧 이 나라에 들어온 돈의 지도예요." },
    { y: "2015~20", t: "배달과 게임, 세계에 팔리다", wk: "Peak_Games", co: ["예멕세페티", "딜리버리히어로", "피크 게임즈", "징가", "드림 게임즈"],
      toon: [["🍕", "이스탄불 음식 배달 앱, 5억 8,900만 달러에 독일로."], ["🎮", "퍼즐 게임 회사가 튀르키예 첫 유니콘 매각이 됐어요. 18억 달러."]],
      b: "2015년 독일 **딜리버리히어로**가 음식 배달 **예멕세페티**를 5억 8,900만 달러에 샀어요. 그때까지 음식 배달 업계 최대 인수였어요. 창업자는 매각 대금 일부를 직원들과 나눠 화제가 됐어요.\n2020년 미국 징가가 이스탄불의 모바일 게임 회사 **피크 게임즈**를 18억 달러에 샀어요. 튀르키예 스타트업 첫 조 단위 매각이었어요.\n피크 출신들이 **드림 게임즈**(로열 매치) 등을 세워 이스탄불은 모바일 게임의 중심지가 됐어요.",
      w: "딜리버리히어로는 배달의민족도 산 그 회사예요. 한 번의 큰 매각이 다음 창업자를 낳는 무늬가 여기서도 보여요." },
    { y: "2018~21", t: "트렌디욜과 게티르, 그리고 리라 위기", wk: "Trendyol", co: ["트렌디욜", "알리바바", "게티르", "헵시부라다", "소프트뱅크", "제너럴 애틀랜틱"],
      toon: [["🛍️", "알리바바가 고른 튀르키예 쇼핑 앱, 기업가치 165억 달러."], ["🛵", "10분 장보기 배달, 이스탄불에서 런던·뉴욕까지 갔다가…"]],
      b: "2018년 리라 값이 한 해 30% 가까이 떨어지는 통화 위기가 왔어요. 같은 해 중국 **알리바바**가 쇼핑 앱 **트렌디욜**의 큰 지분을 샀어요. 2021년 트렌디욜은 기업가치 165억 달러로 튀르키예 첫 '데카콘'이 됐어요.\n10분 배달 **게티르**는 2022년 기업가치 약 118억 달러까지 갔지만, 금리가 오르자 2024년 해외 사업을 접었어요. 경쟁사 **헵시부라다**는 2021년 나스닥에 상장했어요.",
      w: "돈이 넘칠 때 해외로 뻗었다가 접는 모습은 2021년 붐 회사들의 공통 결말이에요." },
    { y: "2021~", t: "거꾸로 간 금리와 정통 복귀", wk: "Central_Bank_of_the_Republic_of_Turkey", co: ["튀르키예 중앙은행", "보르사 이스탄불", "튀르키예 국부펀드"],
      toon: [["📉", "물가가 오르는데 금리를 내리면 어떻게 되죠?"], ["🧮", "물가 상승률이 한때 80%를 넘었어요."]],
      b: "2021년부터 정부는 '금리를 내려야 물가가 잡힌다'며 금리를 내렸어요. 리라 값은 급락하고 2022년 물가 상승률은 공식 통계로도 80%를 넘었어요.\n물가를 피하려는 개인 돈이 주식으로 몰려 **보르사 이스탄불**은 폭등했어요.\n2023년 선거 뒤 메흐메트 심셰크가 재무장관으로 돌아와 금리를 다시 크게 올렸어요. 외국 돈이 조심스레 돌아오기 시작했어요.",
      w: "'금리와 물가, 환율이 어떻게 이어지나'를 가장 극적으로 보여 주는 나라. 튀르키예 딜 기사 금액은 리라인지 달러인지 꼭 보세요." } ] },

  { id: "me", flag: "🕌", name: "중동 (걸프·이스라엘)", intro: "석유로 번 돈이 국부펀드가 되어 세계를 사고, 이스라엘은 '스타트업 나라'가 됐어요. 아람코·PIF·무바달라·ADIA·웨이즈·모빌아이가 나와요.", items: [
    { y: "1933~38", t: "사막의 계약, 아람코의 시작", wk: "Saudi_Aramco", co: ["스탠더드오일 오브 캘리포니아(지금의 셰브론)", "아람코", "텍사코", "엑슨", "모빌"],
      toon: [["🐪", "돈이 급하오. 금화 3만 5천 파운드에 석유 찾을 권리를 드리지."], ["🛢️", "5년을 허탕 치다 일곱 번째 우물에서 터졌어요."]],
      b: "1933년 갓 세워진 사우디 왕국은 미국 **스탠더드오일 오브 캘리포니아**(지금의 셰브론)에 석유 탐사권을 줬어요. 1938년 담맘의 일곱 번째 우물에서 석유가 터졌어요.\n이 회사가 **아람코**(아라비안 아메리칸 오일 컴퍼니)예요. 뒤에 텍사코, 엑슨, 모빌이 주주로 들어왔어요. 록펠러의 스탠더드오일이 쪼개져 나온 회사들이에요.\n1950년 사우디는 이익을 절반씩 나누기로 계약을 고쳤어요.",
      w: "세계에서 가장 값진 회사의 출발이 미국 석유회사와의 계약이었어요. 지금도 사우디와 미국 관계의 바닥에 이게 있어요." },
    { y: "1953", t: "세계 첫 국부펀드, 쿠웨이트", wk: "Kuwait_Investment_Authority", co: ["쿠웨이트 투자청(KIA)", "아부다비 투자청(ADIA)"],
      toon: [["🫙", "석유는 언젠가 떨어져. 번 돈을 런던에 넣어 불려 두자."], ["🌍", "그렇게 '나라의 저금통'이 생겼어요."]],
      b: "1953년 쿠웨이트는 석유 수입을 굴릴 사무소를 런던에 열었어요. 세계 첫 국부펀드로 꼽히는 **쿠웨이트 투자청**의 시작이에요.\n1976년에는 아부다비가 **아부다비 투자청(ADIA)**을 만들었어요. 지금도 세계에서 가장 큰 국부펀드 가운데 하나예요.\n1990년 이라크가 쿠웨이트를 침공했을 때, 나라 밖에 둔 이 돈이 망명 정부와 재건의 밑천이 됐어요.",
      w: "투자 기사에서 KIA, ADIA, PIF, 무바달라, QIA는 다 이런 '나라 돈'이에요. 사모펀드의 가장 큰 전주들이에요." },
    { y: "1973~80", t: "석유 무기, 그리고 아람코 국유화", wk: "1973_oil_crisis", co: ["OPEC", "사우디 아람코", "씨티은행 등 미국 은행들"],
      toon: [["⛽", "석유를 줄이겠소. 값은 네 배."], ["💵", "그렇게 번 달러(페트로달러)는 다시 뉴욕 은행으로 갔어요."]],
      b: "1973년 중동 전쟁 때 아랍 산유국들이 석유 수출을 줄여 값이 몇 달 만에 네 배가 됐어요. 주유소에 줄이 늘어섰고 세계는 불황에 빠졌어요.\n산유국에 달러가 쌓였어요. 이 **페트로달러**는 미국 국채와 서방 은행으로 돌아갔고, 은행들은 그 돈을 중남미에 빌려줬다가 1980년대 빚 위기를 겪었어요.\n사우디는 아람코 지분을 조금씩 사들여 1980년 100% 나라 것으로 만들었어요.",
      w: "'석유를 달러로만 판다'는 구조가 이때 굳어졌어요. 달러가 세계 돈인 이유 가운데 하나예요." },
    { y: "1993", t: "요즈마: 정부가 벤처캐피털을 만들다", wk: "Yozma", co: ["요즈마 펀드", "체크포인트", "미라빌리스(ICQ)", "AOL"],
      toon: [["🧑‍🔬", "소련에서 과학자 수십만 명이 왔는데 일자리가 없어요."], ["🤝", "정부가 40% 댈게요. 잘되면 싸게 되사 가세요."]],
      b: "1990년대 초 이스라엘에는 군 기술 인력과 소련에서 이민 온 과학자가 넘쳤지만 투자할 돈이 없었어요.\n1993년 정부가 1억 달러로 **요즈마**를 만들었어요. 외국 벤처캐피털이 이스라엘 펀드를 만들면 정부가 40%를 대고, 성공하면 정부 몫을 싸게 되살 권리를 줬어요. 10개 펀드가 생겼고 대부분 성공해 정부는 손을 뗐어요.\n1998년 메신저 ICQ를 만든 **미라빌리스**가 AOL에 약 4억 달러에 팔리며 첫 대박이 나왔어요.",
      w: "한국의 모태펀드(2005)를 비롯해 여러 나라가 본뜬 모델. '정부가 마중물을 붓고 빠진다'의 교과서예요." },
    { y: "2009", t: "두바이 쇼크", wk: "Dubai_World", co: ["두바이월드", "나킬", "에마르", "아부다비 정부"],
      toon: [["🏝️", "야자수 모양 인공섬에 세계 최고층 빌딩까지!"], ["⏸️", "빚 갚는 걸 여섯 달만 미뤄 주세요…"]],
      b: "석유가 적은 두바이는 빚을 내서 관광·부동산·물류 도시를 지었어요. 인공섬을 만든 **나킬**, 부르즈 할리파를 지은 **에마르**가 주역이었어요.\n금융위기로 부동산 값이 반 토막 나자, 2009년 11월 국영 지주회사 **두바이월드**가 약 260억 달러 빚의 상환을 미뤄 달라고 했어요. 세계 증시가 흔들렸어요.\n이웃 아부다비가 100억 달러를 내줘 고비를 넘겼어요. 준공을 앞둔 세계 최고층 빌딩 이름이 '부르즈 두바이'에서 아부다비 통치자의 이름을 딴 '부르즈 할리파'로 바뀌었어요.",
      w: "빚으로 지은 성장은 돈줄이 마르면 선다는 것. 그리고 UAE 안에서 돈줄을 쥔 쪽은 아부다비라는 것." },
    { y: "2013~17", t: "웨이즈와 모빌아이: 스타트업 나라의 대형 매각", wk: "Mobileye", co: ["웨이즈", "구글", "모빌아이", "인텔", "8200부대 출신 창업자들"],
      toon: [["🗺️", "운전자들이 서로 길을 알려 주는 앱, 구글이 11억 달러에."], ["🚘", "자동차의 눈을 만드는 회사, 인텔이 153억 달러에."]],
      b: "인구 900만의 이스라엘은 1인당 스타트업 수가 세계에서 가장 많은 나라가 됐어요. 군 정보 부대 출신들이 보안·센서 회사를 세웠어요.\n2013년 구글이 길 안내 앱 **웨이즈**를 약 11억 달러에 샀어요. 2017년에는 인텔이 자율주행 카메라 칩 회사 **모빌아이**를 153억 달러에 샀어요. 당시 이스라엘 최대 매각이었어요.\n이스라엘 회사들은 크기 전에 미국 회사에 팔리는 경우가 많아요.",
      w: "'기술은 이스라엘, 사는 쪽은 미국 빅테크'. 2025년 구글이 보안 회사 위즈를 320억 달러에 사기로 한 것도 같은 줄기예요." },
    { y: "2016~17", t: "비전 2030과 PIF의 등장", wk: "Public_Investment_Fund", co: ["사우디 국부펀드(PIF)", "우버", "소프트뱅크 비전펀드", "루시드", "네옴"],
      toon: [["🕋", "석유 없이도 사는 나라를 만들겠습니다. — 비전 2030"], ["📲", "그 첫 수: 우버에 35억 달러, 비전펀드에 450억 달러."]],
      b: "2016년 사우디의 젊은 실권자 무함마드 빈 살만이 '비전 2030'을 내놓았어요. 석유에 기대는 경제를 바꾸겠다는 계획이에요. 도구는 **국부펀드 PIF**.\nPIF는 그해 **우버**에 35억 달러를 넣었고, 2017년 손정의의 **비전펀드**에 450억 달러를 약속했어요. 한 번의 만남에서 정해졌다는 이야기가 유명해요.\n이후 전기차 **루시드**, 게임, 스포츠, 신도시 **네옴**으로 넓혔어요.",
      w: "2010년대 후반 실리콘밸리에 넘친 돈의 큰 줄기가 사우디였어요. 딜 기사에 PIF가 나오면 이 계획의 일부예요." },
    { y: "2017~19", t: "수크와 카림: 중동 스타트업의 첫 회수", wk: "Careem", co: ["수크닷컴", "아마존", "카림", "우버", "STC"],
      toon: [["📦", "'중동의 아마존'을 진짜 아마존이 샀어요."], ["🚕", "차량 호출 카림은 우버가 31억 달러에."]],
      b: "2017년 아마존이 두바이의 쇼핑몰 **수크닷컴**을 약 5억 8천만 달러에 샀어요. 2019년에는 우버가 차량 호출 **카림**을 31억 달러에 샀어요. 중동 기술 회사 사상 최대 매각이었어요.\n카림에 일찍 투자한 사우디 통신사 **STC** 등이 큰돈을 벌었고, 카림 출신 수백 명이 창업자와 투자자가 됐어요. 이들을 '카림 마피아'라고 불러요.",
      w: "플립카트, 피크 게임즈와 같은 무늬. 큰 매각 한 번이 그 지역 창업 생태계의 씨앗이 돼요." },
    { y: "2019", t: "아람코, 세계 최대 상장", wk: "Tadawul", co: ["사우디 아람코", "타다울(사우디 거래소)", "애플"],
      toon: [["🏆", "세계에서 가장 돈을 많이 버는 회사가 주식시장에 나옵니다."], ["🇸🇦", "해외 상장은 접고, 리야드 거래소에만 올렸어요."]],
      b: "2019년 12월 **아람코**가 리야드의 **타다울** 거래소에 상장했어요. 지분 1.5%를 팔아 약 256억 달러를 모았어요(추가 물량까지 약 294억 달러). 알리바바를 넘는 세계 최대 상장이었어요.\n상장 직후 기업가치는 2조 달러에 닿아 애플을 넘었어요.\n처음엔 뉴욕이나 런던 상장을 꿈꿨지만, 공개해야 할 정보와 소송 위험 때문에 국내 상장으로 돌렸어요.",
      w: "판 돈은 PIF로 가서 '탈석유' 투자에 쓰였어요. 상장이 '돈을 구하는 일'이면서 '정보를 내놓는 일'이라는 점도 보여 줘요." },
    { y: "2020~25", t: "걸프 돈이 게임·스포츠·AI로", wk: "Mubadala_Investment_Company", co: ["PIF", "무바달라", "MGX", "카타르 투자청(QIA)", "스코플리", "일렉트로닉 아츠(EA)", "실버레이크", "오픈AI"],
      toon: [["⚽", "축구단, 골프 리그, 게임 회사… 다 삽니다."], ["🤖", "이제는 AI 데이터센터에 수백억 달러씩."]],
      b: "2021년 PIF 주도 컨소시엄이 영국 축구단 뉴캐슬을 샀고, 2022년에는 골프 리그 LIV를 만들었어요. 2023년 PIF 산하 게임 회사가 미국 **스코플리**를 49억 달러에 샀어요.\n2025년에는 PIF와 사모펀드 실버레이크 등이 게임사 **EA**를 약 550억 달러에 비상장으로 사겠다고 발표했어요. 성사되면 사상 최대 차입 매수예요.\n아부다비는 **무바달라**와 2024년 만든 AI 투자사 **MGX**로 오픈AI 등 AI 회사와 데이터센터에 큰돈을 넣고 있어요.",
      w: "요즘 큰 딜의 '돈 대는 쪽'에 걸프 이름이 빠지지 않는 이유. 석유 돈이 다음 시대의 자산으로 옮겨 가는 중이에요." } ] },
] });
